export function applyDeepStudyEnhancement(note: StudyNote): StudyNote {
  const enhancement = deepStudyEnhancements[note.range] ?? earlyDeepStudyEnhancements[note.range];
  return enhancement ? { ...note, ...enhancement } : note;
}

type StudyNoteDetails = Pick<StudyNote, 'verseInsights' | 'interpretationNotes' | 'citations'>;

function n(range: string, title: string, scene: string, scripture: string, literal: string, context: string, connection: string, life: string, details: StudyNoteDetails = {}): StudyNote {
  return { range, title, scene, scripture, literal, context, connection, life, ...details };
}

export const chapterNotesByChapter: Record<number, StudyNote[]> = {
  2: [
    n('2:1–7', '客房里没有他们的地方', '把自己放进罗马帝国命令传到乡间的那一天：约瑟带着已经怀孕的马利亚，离开拿撒勒，走向大卫的城伯利恒。旅途、登记、拥挤和生产的紧迫感同时压在这对年轻夫妻身上；孩子出生后，只能被放在喂牲畜的槽里。', '耶稣在伯利恒出生，被放在马槽里；路加把祂的降生放在帝国命令与普通人的迁徙之中。', '“没有地方”并不只是一个温馨故事的布景，而是从第一幕就显出耶稣的道路：祂进入人的脆弱、拥挤和不被优先安排的位置。马利亚把婴孩包起来，约瑟承担照料；救主先以一个需要被抱起的孩子出现。', '经文把故事放入凯撒下令、地方行政登记和希律统治的历史空气中；关于登记的具体时间与行政方式，学界仍有讨论，不应把细节争议遮盖经文的焦点。伯利恒与大卫家族的联系，使“在大卫的城出生”同时带有地理和应许意义。“客店”也可理解为客房或住宿空间，文本没有要求我们把它想象成现代旅馆。', '可对照弥 5:2、撒下 7:12–16 与太 1:18–25：弥迦所说的小伯利恒成为大卫之子的所在；腓 2:6–8 则把这种“降卑”解释为基督主动取了奴仆的形象。', '讨论：我们是否只在体面、宽敞、有掌控感的地方寻找神？操练：留意一处“没有被优先安排的人”的需要，用一个具体行动把位置让出来。'),
    n('2:8–20', '夜班牧羊人听见大喜的信息', '夜色覆盖伯利恒附近的山坡，牧羊人守着羊群，轮流警醒。忽然，荣耀照亮旷野；他们不是先收到宫廷和圣殿的通知，而是在工作现场听见“为你们生了救主”的宣告，然后匆忙走进城里寻找一个包着布、躺在马槽里的婴孩。', '天使向牧羊人宣告救主降生；他们看见耶稣后把所听见、所看见的传开，并归荣耀给神。', '天使给出的记号极其普通：一个婴孩、布、马槽。牧羊人不是被宏大的视觉留住，而是让所听见的话带他们去看；看见之后，他们又成为传讲者。马利亚则把这些话存在心里，反复思想，显示信仰既有公开见证，也有安静咀嚼。', '牧羊人在当时社会中常被视为边缘而辛苦的劳动者；我们不必把他们浪漫化，也不应把他们简单等同于不诚实的人。路加将“在至高之处荣耀归与神，在地上平安归与祂所喜悦的人”放在罗马“和平”宣传的背景旁边，提示真正的平安来自神的临在。', '可回看诗 23、赛 9:2–7 与结 34:11–16，听见牧者、黑暗中的光和神亲自寻找羊群的回声；约 10 章进一步把耶稣描写为好牧人。', '讨论：什么声音最容易定义我们对“平安”的理解——新闻、权力、收入，还是神的应许？操练：把本周听到的一条焦虑消息，改写成一段以神的临在为中心的祷告，并为一人传递真实而不夸张的盼望。'),
    n('2:21–24', '在律法之下被献上的孩子', '耶路撒冷圣殿里，人群来来往往。一个普通家庭抱着婴孩进入敬拜空间，按着律法给祂行割礼、取名，并献上祭物；没有仪仗、没有公开掌声，只有一对父母用最日常的礼仪把孩子交在神面前。', '耶稣受割礼、被取名，并按摩西律法被带到耶路撒冷献给主。', '路加连续写出“照律法”“照主的律法”，表明耶稣不是脱离以色列故事的神秘人物，而是在以色列的约、礼仪和家庭生活中进入世界。祂的身份不是靠拒绝历史而显大，而是在顺服中显明。', '初生男孩的割礼、长子的奉献和洁净礼都属于以色列家庭生活与敬拜秩序。经文引用的是穷人可以献上的鸟类祭物（利 12:8），暗示这个家庭并不富裕；这也使“救主”与普通家庭的经济现实紧紧相连。', '可连到出 13:1–2、利 12:1–8 与加 4:4–5：保罗说神的儿子生在律法以下，为要把在律法以下的人赎出来；路加的叙事让这句话先成为一个婴孩的具体经历。', '讨论：我们有没有把属灵成长想象成脱离普通责任？操练：把一个家庭、工作或身体照顾上的日常责任，重新当作献给主的服事来完成。'),
    n('2:25–40', '西面与亚拿：在等候中认出救恩', '圣殿的院落中，年长的西面抱起婴孩；他的手臂或许已经习惯了等待，却在这一刻认出“眼睛看见了你的救恩”。女先知亚拿也走近，向所有盼望耶路撒冷得救赎的人讲说这孩子。一个家庭的奉献，成为等候者的公开见证。', '西面称耶稣为照亮外邦人的光和以色列的荣耀；亚拿不断祷告、禁食，在孩子身上向人讲说神的救赎。', '西面的歌既有安慰也有刺痛：这孩子将使人跌倒、兴起，也会使马利亚经历像刀刺一样的痛。救恩不是廉价的成功保证，而是神进入真实冲突、揭露人心并承担苦难。亚拿的等候没有使她被动，她以祷告和见证参与神的工作。', '圣殿是以色列共同记忆的中心；路加让一位老人和一位女先知成为辨认弥赛亚的关键人物，改变了“只有年轻、男性、掌权者才是历史主角”的想象。文中的“安慰”与“救赎”也回应当时在外邦统治下对神复兴锡安的盼望。', '可对照赛 42:6、49:6、52:9–10 与诗 98:2–3，理解“外邦人的光”不是临时口号；徒 13:47 又把这条使命线带进教会向列国的见证。', '讨论：等候会不会让我们变得麻木，还是让我们更会辨认神的作为？操练：为教会中一位长期忠心却不被看见的人写一段感恩，并实际聆听他的信仰故事。'),
    n('2:41–52', '十二岁少年留在圣殿', '逾越节人潮从耶路撒冷退去，约瑟和马利亚走了一天才发现孩子不在同行队伍中。他们在亲友之间寻找，最后回到圣殿，看见十二岁的耶稣坐在教师中间，一面听，一面问。焦急的父母与专注于父家事务的孩子，在这里相遇。', '耶稣说自己应当以父的事为念，却仍回到拿撒勒顺服父母；祂的智慧和身量一同增长。', '这段经文既显出耶稣独特的身份，也保留家庭关系中的真实张力。祂没有用“属灵使命”逃避成长责任，而是在圣殿的清楚召命与家中的顺服之间走完隐藏岁月。路加最后把镜头放在智慧、身量、神和人喜爱祂一同增长上。', '逾越节朝圣会形成有亲族与乡人同行的队伍，孩子可能与群体中的不同队伍往来；经文不是要责备父母疏忽，而是描写寻找与重新发现。圣殿教师之间的问答属于犹太教学习传统，耶稣既在听也在发问。', '可回看撒上 2:26 中撒母耳在圣所渐渐长大，也可对照箴 3:1–4、路 2:40 与西 1:9–10；耶稣的成长不是跳过人性，而是在父神的旨意中完全活出人性。', '讨论：我们怎样同时尊重孩子真实的提问，又不把他们塑造成自己的信仰复制品？操练：本周给一位年轻人一个不急着纠正的聆听时段，问他“你最近在神面前真正困惑什么？”'),
  ],
  3: [
    n('3:1–6', '在帝国年份里，神的话临到旷野', '请把镜头拉到提庇留在位第十五年：罗马权力、地方分封王、宗教领袖的名字一一出现，像一张政治地图。就在这些名字占满公共空间时，神的话没有先临到宫殿或圣殿，而是临到旷野里的约翰。', '约翰在旷野传悔改的洗礼，应验以赛亚“预备主的道”的话。', '路加把约翰放入具体统治者的年份，不让救恩只悬在神话时间里；同时，旷野宣告神主动重新开始。预备道路不只是在心里有感觉，也包括填平、削平、修直——人的生命与群体关系都要让王经过。', '古代统治者会修筑道路、安排巡行，以显示权力和秩序。以赛亚 40 章原本向被掳者宣告神带领归回；路加借用这幅图像，宣告神的拯救再次临近，并且要让“凡有血气的”看见。', '可串联赛 40:3–5、玛 3:1 与出 23:20；约 1:23、徒 13:24–25 也把约翰定位为预备者，而不是把聚光灯留在自己身上。', '讨论：我们想要神来改变什么，却不愿先让哪条道路被修直？操练：选一段需要修复的关系，先采取一个不带辩护的诚实行动：道歉、澄清或停止传播未经证实的话。'),
    n('3:7–14', '悔改要结出与身份相称的果子', '人群从城里来到河边，法利赛人、撒都该人、普通百姓、税吏和兵丁站在同一个水边。约翰没有让他们用“我们有亚伯拉罕作祖宗”挡住审问，而是把问题落到衣服、饭食、金钱和权力：你真正改变了吗？', '约翰要求人用实际行动证明悔改：有两件衣服的分给没有的，税吏不多取，兵丁不强暴、不讹诈。', '悔改不是厌恶自己，也不是换一个宗教标签；是停止利用位置占便宜，开始让邻舍在我们的生活中得益处。约翰对不同职业给出不同回应，说明悔改不是抽象情绪，而是进入具体制度与日常选择。', '税吏为罗马征收税款，容易处在利益与不信任交错的位置；兵丁则拥有强制力。约翰没有要求所有人立刻离开职业，而是先处理贪婪、暴力和勒索，显示神的更新要触及工作方式与权力使用。', '可对照弥 6:8、赛 58:6–7、利 19:9–18；雅 2:14–17 和路 19:8 会再次说明，真实的回转会在金钱和邻舍关系上留下痕迹。', '讨论：我们最容易把“悔改”说成态度，却不落实在哪个生活领域？操练：检查一次消费、报销、工作分工或网络发言，找出一个可以更诚实、更慷慨的调整。'),
    n('3:15–20', '约翰不是基督，火也不是表演', '人群被约翰的勇敢吸引，心里猜想他或许就是基督。约翰却把自己往后退，说将来的那一位能力更大，祂要用圣灵与火施洗。镜头随后转向希律：同一个先知的声音也会触碰王的婚姻与权力，因此约翰被囚。', '约翰把盼望指向比自己更大的耶稣，并因责备希律的罪而被关押。', '属灵领袖的成熟，不是让人越来越依赖自己，而是把人交还给基督。约翰的信息也表明，真理会进入公共道德和权力关系；见证不是为了保持安全形象。', '“用火施洗”可与洁净、审判和圣灵的工作相连，不能只简化为一种情绪体验。希律安提帕是加利利和比利亚的分封王，受罗马体系约束却拥有地方权力；约翰的被囚说明先知性言论会付出真实代价。', '可对照玛 3:11–12、珥 2:28–29、赛 4:4；徒 2 章的圣灵降临让“圣灵”这条应许继续展开，而路 9:7–9 将再次提到约翰的被囚与希律的困惑。', '讨论：我们是否只欢迎不会令自己不舒服的属灵信息？操练：请一位成熟信徒指出你一个长期重复的盲点；先只听完、复述，再决定怎样回应。'),
    n('3:21–22', '在众人受洗时，天开了', '耶稣站在约旦河边，与众人一起受洗。祂没有以旁观者身份进入人群，而是在祷告中被天开启；圣灵仿佛鸽子降下，声音宣告祂是蒙爱的儿子。公开使命先从父的肯定开始。', '耶稣受洗并祷告时，圣灵降临，父神宣告祂是所喜悦的儿子。', '耶稣的身份不是由群众反应、事工成果或旷野试探决定；在任何公开工作之前，祂先被称为蒙爱的儿子。祷告与受洗把耶稣放在神与人相遇的交界处，三一神的行动也在这里显明。', '约旦河连接约书亚进入应许地、以利亚和以利沙的先知传统，也承载约翰呼召以色列回转的象征。天上的声音可能回响诗 2:7 的君王语言与赛 42:1 的仆人语言，王权与受苦的使命在耶稣身上相遇。', '可对照诗 2:7、赛 42:1、创 22:2 与太 3:13–17；罗 6:3–4 又把受洗连接到与基督同死同活的门徒身份。', '讨论：当没有成果、掌声或别人认可时，我们凭什么知道自己是谁？操练：每天祷告前先用一句经文宣告“我是在神所爱中行动的人”，再面对当天的任务。'),
    n('3:23–38', '家谱走到亚当，走向全人类', '镜头从约旦河边的耶稣慢慢向后退，经过约瑟、所罗巴伯、大卫、亚伯拉罕，最后抵达亚当，抵达“神的儿子”。这不是一张冷冰冰的名单，而是一条把耶稣与以色列、被掳、列祖和每一个人连在一起的路。', '路加列出耶稣的家谱，从约瑟一路追溯到亚当，强调祂进入整个人类的历史。', '路加没有把耶稣写成脱离家族与民族的神秘英雄；同时，他把家谱延伸到亚当，使救恩的视野超过单一民族。家谱中的名字也提醒我们，神的工作常穿过复杂、不完美、甚至断裂的历史。', '古代家谱可以表达血缘，也可以表达合法身份、王权归属和神学主题；马太从亚伯拉罕写到耶稣，路加从耶稣写回亚当，重点不同。我们不必把两份家谱强行拼成一份现代户籍表。', '可对照创 1–5、撒下 7:12–16、罗 5:12–19 与林前 15:45–49：亚当带出人类共同处境，基督作为末后的亚当带来新的起头。', '讨论：我们最常用哪一种身份给别人和自己排序——血缘、教育、国籍、成就还是基督？操练：在小组中分享一个塑造你很深的家庭故事，同时说出福音如何给这段历史新的解释。'),
  ],
  4: [
    n('4:1–13', '旷野里，先确定你是谁', '约旦河的水还没有从记忆中退去，耶稣被圣灵引到旷野。四十天没有食物，身体的饥饿、身份的疑问和“立刻证明自己”的诱惑一起出现：如果你是神的儿子，就把石头变成食物；如果你是王，就跳下去让众人看见。', '耶稣在旷野中拒绝把儿子的身份建立在满足欲望、操控神迹或敬拜权力上。', '三个试探都在问同一个问题：你要怎样使用身份？耶稣用申命记的话回应，不把神的话当作操纵工具，也不以成功证明父的爱。祂胜过试探，不是靠展示超能力，而是在饥饿中仍信靠父。', '旷野让人想到以色列出埃及后四十年的试验；耶稣引用申 8、6、6 的经文，重走以色列的道路，却在饥饿与权力诱惑中忠心。圣殿顶的具体位置不必被戏剧化，重点是把神变成表演的后台。', '可对照申 6–8 章、创 3 章与来 4:15–16；马太也记载相同试探，但路加把最后一试放在圣殿，预先指向耶路撒冷的冲突。', '讨论：我们最常用什么来证明“我值得被爱”——效率、属灵表现、影响力或控制感？操练：在一次被催促立刻证明自己的场景中，先停三分钟祷告，再作不操控他人的决定。'),
    n('4:14–21', '拿撒勒会堂里，今日应验了', '安息日，耶稣回到自己长大的拿撒勒。会堂里的人认识祂的家庭和成长背景；祂站起来读以赛亚书，宣布受膏者要向贫穷人传福音、释放被掳的、叫瞎眼的看见。然后祂合上书卷，说：今天这话应验了。', '耶稣以以赛亚的禧年与释放应许说明自己的使命，并把它宣告为当下已经开始的事实。', '耶稣的使命同时关乎宣讲、释放、医治和恩年；福音不是只有灵魂离开世界，也不是只有社会工程，而是神的国触及被压碎的人。祂没有先列出个人成就，而是让圣经定义自己要做什么。', '会堂是读经、祷告和解释经文的地方；以赛亚 61 章与 58 章的语言连接被掳后的复兴、禧年债务释放和对贫穷者的公义。路加删略了以赛亚中关于报仇的部分，突出恩典临到人的“今日”。', '可对照赛 61:1–2、赛 58:6–7、利 25:8–12，并回到路 7:22 看耶稣如何用实际行动回答约翰；徒 4:27–30 则把受膏者的使命带进教会祷告。', '讨论：我们的“福音”是否足以触碰贫穷、被排斥、成瘾、孤独和不公？操练：在本周选一个被忽略的人群，先听一个真实故事，再决定自己能承担的一项长期而非象征性的行动。'),
    n('4:22–30', '熟悉感变成绊脚石', '会堂里的人先惊讶，再低声说：“这不是约瑟的儿子吗？”他们熟悉耶稣的家乡，却拒绝接受神可以透过一个熟悉的人带来新的工作。耶稣提起以利亚和以利沙帮助外邦人的故事，气氛骤然从赞叹变成愤怒。', '拿撒勒人因耶稣不迎合本地期待而拒绝祂；耶稣指出神的恩典也临到外邦人。', '“我们听见在迦百农所行的事，也当行在你自己家乡”显出一种把神迹当作地方特权的心态。耶稣不是因为缺乏能力才被拒绝，而是因为祂的恩典不接受人的圈地；熟悉经文的人也可能抵挡经文正在做的新事。', '以利亚在旱灾中帮助西顿撒勒法的寡妇，以利沙医治叙利亚的乃缦（王上 17；王下 5），都是以色列先知恩典越过民族边界的例子。拿撒勒地势与会堂细节无需被过度重建，文本的冲突核心是“谁有资格得恩典”。', '可对照王上 17:8–16、王下 5:1–19、约 1:11 与徒 13:46–48；路加在这里预告福音从以色列向万民展开的方向。', '讨论：哪些人一出现，我们就觉得“神不可能先祝福他们”？操练：为一个你本能保持距离的群体，做一次不带优越感的聆听或共同服事。'),
    n('4:31–44', '权柄在会堂、病床与旷野之间', '耶稣下到迦百农，安息日进入会堂。污鬼喊出祂的身份，群众却注意到祂说话带着权柄；随后镜头从会堂转到西门岳母的床边，再转到城门口聚集的病人。耶稣医治之后，天还未亮，祂退到旷野祷告。', '耶稣以话语赶鬼、医治疾病，并在众人寻找祂时坚持到别的城传讲神国。', '耶稣的权柄不是让人围绕祂的奇观，而是释放人、恢复人，并把祂自己带回父的差遣。祂不让医治需求完全决定行程，也不把祷告当作服事之后可有可无的装饰。', '古代人对疾病、污鬼和洁净有不同于现代医学的理解；传统将本福音书作者认作保罗的同工路加，也有人据其描写推测他受过医学训练，但这不能作为经文本身已经证明的事实。此处更稳妥的观察是：作者同时描写身体医治与属灵释放。加利利会堂是学习和敬拜中心，城门则是公共聚集处，耶稣的事工同时进入宗教、家庭和城市生活。', '可对照诗 103:1–5、赛 35:5–6、可 1:21–39 与路 5:15–16；耶稣越被人寻找，越显示祂需要独处祷告，以父的旨意重新定向自己。', '讨论：当需求不断涌来，我们会不会把“别人需要我”误当成“神现在要我做的一切”？操练：为忙碌生活设一个固定的退到旷野时段，哪怕只有二十分钟，先祷告再安排下一步。'),
  ],
  5: [
    n('5:1–11', '把船划到水深之处', '清晨的革尼撒勒湖边，渔夫整夜劳碌却一无所获。群众挤向耶稣，西门把船借给祂作讲台；讲完后，耶稣叫他把船开到水深处下网。鱼群几乎撑破两只船，西门首先看见的却不是收入，而是自己的不配。', '耶稣在丰收的神迹中呼召西门、雅各、约翰，使他们从捕鱼转向得人。', '神迹不是独立的惊奇事件，而是把人带到呼召面前。西门称自己是罪人，耶稣却没有让他停在羞耻里，而是说“不要怕”；新的身份不是“我不配，所以不能跟随”，而是“我承认不配，仍被主差遣”。', '加利利渔业有夜间撒网、清晨清洗和修补的工作节奏；空网意味着真实的经济压力。耶稣坐在船上教导符合湖边地形，也让一艘劳动工具变成公共讲台。', '可对照耶 16:16、结 47:9–10 与约 21:1–19；“得人”不是操纵或捕获，而是参与耶稣把人从死亡带入生命的使命。', '讨论：失败之后，我们最先保护的是面子、收入还是对主的聆听？操练：把一次最近的失败写成三列：我失去什么、神让我看见什么、下一步忠心是什么。'),
    n('5:12–16', '伸手摸那不洁净的人', '一个满身大麻风的人远远站着，不能自然地走入人群。他跪下请求，知道耶稣若肯，便能洁净他。耶稣伸手摸他——不是隔着距离宣布一句话，而是进入一个别人害怕靠近的身体。', '耶稣洁净麻风病人，吩咐他按律法给祭司察看，并在声名扩散时退到旷野祷告。', '病人说“洁净我”，不只是求症状消失，也求重新回到群体、敬拜和家庭。耶稣的触摸不是被不洁净污染，反而使洁净向外流动；祂又叫人经过祭司确认，显示怜悯与群体秩序并不互相排斥。', '圣经中的“麻风”涵盖多种皮肤病，并不等同于现代医学的单一疾病；利 13–14 章把隔离、检查与重新接纳交给祭司判断。病人承受的不只是身体痛苦，还有礼仪与社会隔离。', '可对照利 13–14、王下 5:1–14、诗 51:7；路 17:11–19 会再次写到麻风病人与感恩，来 4:15–16 则让我们看见基督主动靠近人的软弱。', '讨论：我们怎样在保护群体安全的同时，不把病人、成瘾者或失败者永远固定成“脏的人”？操练：了解教会或社区中一个边缘群体的真实需要，并以尊重其自主性的方式提供帮助。'),
    n('5:17–26', '朋友把屋顶打开', '屋里坐满法利赛人和教法师，连门口都挤不进。几位朋友抬着瘫子，从屋顶拆开一条路，把他垂到耶稣面前。耶稣先说“你的罪赦了”，房间里立刻出现一个看不见的争论：谁能赦罪？', '耶稣以医治瘫子证明人子在地上有赦罪的权柄，并使这个人站起来回家。', '耶稣没有把人的身体需要和罪疚简单画等号；祂先赦罪，是在宣告自己拥有只有神能拥有的权柄，然后用可见的医治让不可见的赦免被看见。群众最后不是围绕争论，而是赞美神。', '古代房屋常有平屋顶与外部上屋顶的通道，具体结构因地区而异；故事重点是朋友突破障碍的行动。法利赛人与教法师关心赦罪权柄，反映当时对神圣权柄和圣殿赎罪秩序的严肃理解。', '可对照诗 103:2–3、赛 43:25、但 7:13–14 与约 5:8–9；雅 2:17 也提醒我们，真正的信心会带着人把行动做到屋顶上。', '讨论：我们是把人带到耶稣面前，还是先要求他把自己整理到配得被接纳？操练：为一位正在软弱中的朋友承担一个具体障碍：接送、陪诊、倾听或一起查经。'),
    n('5:27–32', '利未在税关旁站起来', '耶稣走到税关，看见利未坐在那里。周围的人可能只看见一个与罗马税务体系有关系的人；耶稣却先发出一句简短的邀请：“跟从我来。”利未离开桌子，在家中摆设筵席，税吏和罪人坐满屋子。', '利未离开一切跟随耶稣；耶稣说明自己来是召罪人悔改，不是召自以为义的人。', '耶稣的呼召先恢复关系，再展开改变；祂没有等利未完成道德修复才坐席，也没有把坐席当作对罪的认可。法利赛人的问题迫使我们分辨：圣洁不是远离所有受伤的人，而是在不美化罪的情况下，把人带进医治。', '税关是金钱、权力与地方不信任相遇的地方；税吏常因与外邦统治和征收制度相连而被视为不洁，但个别税吏的具体收入方式不能一概而论。筵席在古代社会表达接纳与关系，不只是吃饭。', '可对照何 6:6、结 34:15–16、路 19:1–10；太 9:9–13 与可 2:13–17 也保留这场呼召，显示它是福音核心记号。', '讨论：我们欢迎罪人，是为了让他们被基督改变，还是只为增加人数？操练：邀请一位平常不会出现在教会圈子里的人共享一顿饭，并准备真正听见他的故事。'),
    n('5:33–39', '新酒需要新皮袋', '有人来问：约翰的门徒常常禁食，法利赛人的门徒也禁食，为什么你的门徒又吃又喝？耶稣没有把禁食贬低，而是用婚宴、补衣和新酒的图像说明：当新郎在场，喜乐有它的时刻；新生命也不能被旧的容量硬塞住。', '耶稣以新郎、新衣和新酒说明祂带来的国度需要与之相称的群体节奏。', '门徒生活既有欢宴也有禁食，关键不是用一种外在形式证明敬虔，而是辨认主在何时临在、何时呼召我们哀恸等候。新酒不是追求新奇，而是福音更新人的关系、价值和共同体结构。', '禁食在犹太传统中与悔改、哀哭、寻求神有关；婚宴则是喜乐和弥赛亚盼望的意象。皮袋通常指皮制容器，新的发酵会撑破旧皮袋；耶稣借日常经验讲属灵更新。', '可对照赛 25:6–9、何 2:19–20、珥 2:12–13；徒 13:2–3、14:23 显示初代教会仍然禁食，但不把禁食变成与基督隔绝的仪式。', '讨论：我们教会的传统，哪些真正承载福音，哪些只是因为“以前一直这样”？操练：在保留核心真理的前提下，试验一种更能接住邻舍的新安排，并在小组复盘它结出了什么果子。'),
  ],
  6: [
    n('6:1–11', '安息日是为人的生命', '两个安息日，门徒在田间掐麦穗，耶稣在会堂遇见一只枯干的手。观察祂的人不是在寻找医治的喜乐，而是在等祂犯错。耶稣让那人站在众人面前，问：安息日行善可以不可以？', '耶稣以大卫吃陈设饼和医治枯手宣告，人子是安息日的主；安息日的诫命不能被用来阻止行善。', '耶稣没有取消安息，而是拒绝把安息变成冷漠的借口。掐麦穗的争论触及解释律法的权柄；枯手的医治则把讨论从抽象规则带回一个人的身体与尊严。真正的安息使生命恢复，不使人被观察和定罪。', '安息日涉及出 20:8–11、申 5:12–15 的创造与出埃及记忆；陈设饼的故事在撒上 21 章，显示律法的圣洁与怜悯需要在具体处境中被正确理解。', '可对照何 6:6、弥 6:8、太 12:1–14；来 4:9–11 又把安息的应许指向在基督里停止自我证明、进入神工作的生命。', '讨论：我们有没有用“守规矩”掩盖不愿帮助人的心？操练：安排一个真正使人恢复的安息时段，同时为一位被孤立的人做一件不夺走其尊严的善事。'),
    n('6:12–16', '整夜祷告后，选出十二个人', '山上很安静，众人还不知道会发生什么。耶稣整夜向神祷告，天亮后从门徒中选出十二人。名单里有渔夫、税吏，也有奋锐党人西门；最后还出现一个将要成为卖主者的犹大。', '耶稣在祷告中拣选十二使徒，使他们成为以色列十二支派记忆中的新群体象征。', '十二人的选立不是因为他们已经成熟无误，而是因为他们在耶稣的呼召中被塑造。名单把差异、张力和失败都保留下来，提醒教会的合一不是性格相同，而是在主的差遣中学习彼此相处。', '“十二”回应以色列十二支派，表达神重新聚集百姓的盼望；“使徒”带有被差遣者的意思。西门与马太可能拥有不同政治经验，但经文没有交代他们每天如何解决冲突，不能把想象当历史事实。', '可对照出 24:4、赛 43:1–7 与结 37:21–22；徒 1:12–26 显示十二人群体在犹大离开后重新面对使命与补选。', '讨论：我们作重要决定时，是否只靠效率和偏好，还是愿意把时间放进祷告？操练：下次小组或家庭面临决定，先共同安静祷告一段时间，再分别说出“我听见了什么”和“我仍担心什么”。'),
    n('6:17–26', '平原上的福与祸', '耶稣与门徒站在平地，下面是从各地来的人群：有人要听道，有人要得医治，有人被污鬼搅扰。祂抬眼看门徒，说贫穷、饥饿、哀哭和被拒绝的人有福；又向富足、饱足、喜笑、受人称赞的人发出警告。', '耶稣颠倒人通常用来判断“过得好不好”的标准，把神的国带给失去保障的人。', '“有福”不是把贫穷和痛苦本身浪漫化，也不是说富足必然有罪；它宣告神看见并将介入被压碎者的处境。“祸”是警报：当人已经用今生的充足封闭自己，就听不见天国的需要。', '古代加利利的贫富差距、债务和土地压力，使饥饿与富足不只是个人感觉。路加特别保留对富足者的警告，与他的读者中可能有资源、有社会位置的人形成正面张力。', '可对照诗 1、诗 37:16–19、诗 146:7–9 与赛 61:1–3；雅 2:1–7、5:1–6 把这份警告带入教会如何对待穷人。', '讨论：我们衡量“蒙福”时，哪些人会被自动排除？操练：盘点一次家庭预算和时间表，刻意为分享、接待或支持有需要的人留下真实空间。'),
    n('6:27–36', '爱仇敌，像天父一样怜悯', '人群中有被伤害、被占便宜、被仇恨包围的人。耶稣没有给出一套漂亮口号，而是说要祝福咒诅你的人，为凌辱你的人祷告；有人打你右脸，连左脸也转过来。祂把门徒从报复循环中拉出来。', '耶稣命令门徒爱仇敌、善待仇恨自己的人，并以天父的怜悯作为群体生活的尺度。', '爱仇敌不是说邪恶无所谓，也不是禁止受害者求助、设界限或寻求公义；它首先拒绝让仇恨决定自己的行动。耶稣要求门徒主动行善、借给人不指望回报，因为父的恩慈临到忘恩负义的人。', '古代荣辱文化中，脸、外衣和借贷都涉及身份与权力；耶稣的教导挑战以牙还牙，也挑战把恩惠只给“对我有用的人”的互惠逻辑。面对暴力时，教会需要同时保护受害者并拒绝复仇。', '可对照出 23:4–5、利 19:17–18、箴 25:21–22；罗 12:14–21 与彼前 2:21–23 展开基督徒如何在不报恶的同时寻求善。', '讨论：对仇敌的爱在具体关系里最小而真实的一步是什么？操练：为伤害过你的人祷告时，不先祈求他失败，而先求神保守你不被苦毒塑造；必要时也建立安全界限。'),
    n('6:37–49', '先取掉自己的梁木', '耶稣继续说到群体中最难的相处：有人眼中有刺，自己却看不见眼中的梁木；有人称呼“主啊”，却不照祂的话行。最后，暴雨、河水冲击房屋的画面落下来，真正的根基在于听见并实行。', '门徒不可假冒审判；好树结好果子，听见耶稣的话并实行的人像把根基立在磐石上。', '耶稣不是取消分辨，而是先处理自我欺骗，再帮助弟兄。言语和果子揭露内心，危机则揭露根基；属灵知识若不进入宽恕、诚实和行动，只会成为倒塌时更大的自欺。', '“梁木”和“刺”来自木工与日常生活的夸张比喻；在重视言语与名誉的群体里，假冒的教师尤其危险。房屋比喻没有承诺门徒不会遇见洪水，而是说明根基决定风暴中的结果。', '可对照诗 1:1–3、申 6:4–9、结 33:30–32；雅 1:22–25、3:1–12 进一步说明听道、言语和行为不可分开。', '讨论：我们最爱指出别人哪一种问题，而自己在哪方面重复同样模式？操练：给一位可信任的组员一个具体授权，请他指出你的盲点；本周只练习一项对应行动，不急着教导别人。'),
  ],
  7: [
    n('7:1–10', '远处的一句话，足以使仆人痊愈', '迦百农的街道上，一位百夫长的仆人病得要死。这个掌握命令权的人没有直接闯进耶稣面前，而是请犹太人的长老代求；等耶稣快到家时，他又觉得自己不配接待，只求主说一句话。', '百夫长相信耶稣只需说一句话，仆人就会痊愈；耶稣称赞这在以色列中也少见的信心。', '信心在这里不是强烈感觉，而是对耶稣权柄的正确判断：百夫长知道命令可以穿越距离，耶稣的权柄不受房屋、身份和空间限制。他关心仆人，也承认自己不配，信心与谦卑同时出现。', '百夫长是罗马治下军队中的基层军官，但故事不能把他简化成完美的“好人”。他与犹太人的关系可能因建造会堂、善待邻人而较好，却仍处于占领秩序之中；路加让这种复杂性留在故事里。', '可对照王上 8:41–43、王下 5:1–14 与诗 107:20；太 8:5–13 也记载这件事，并把“在远处”与外邦人进入神国的盼望连接起来。', '讨论：我们是否只相信神会在自己能控制的范围内工作？操练：为一个你无法亲自介入的处境代祷，把“我必须控制”改成“主，请你说一句话，也教我忠心承担我能承担的部分”。'),
    n('7:11–17', '城门外，哭泣的母亲与生命的主', '拿因城门外，一支送葬队伍迎面而来。一个寡妇失去了独生子，她既失去孩子，也失去家庭在经济与社会上的重要支撑。耶稣看见她，先说“不要哭”，随后摸那抬尸体的架子，众人看见少年坐起来说话。', '耶稣因寡妇的处境动了慈心，使她的独生子复活；众人称祂为大先知，并说神眷顾了自己的百姓。', '耶稣不是被人请来表演神迹，祂主动看见、主动怜悯、主动靠近不洁净的死亡。复活的少年首先“坐起说话”，生命以重新进入关系的声音显明；耶稣把他交还给母亲。', '寡妇在古代社会常缺少丈夫所代表的经济和法律保护，独生子的死亡使她的脆弱更加严重。触摸棺架会带来礼仪洁净的张力；耶稣的触摸显明神的生命与洁净主动临到人，不是把祂写成反对律法，而是把怜悯带到死亡面前。', '可对照王上 17:17–24、王下 4:18–37，听见以利亚、以利沙使寡妇儿子活过来的先知回声；路 9:7–9 也显示耶稣被看作先知，却远超过先知。', '讨论：当别人遭遇无法解决的失去，我们是否急着解释神为什么这样做？操练：陪伴一位哀伤者时，先提供安静、具体的照顾和持续出现，不用属灵答案抢走他的哭泣。'),
    n('7:18–35', '你来的是那一位吗？', '约翰被关在牢里，听见耶稣所做的一切，却没有得到自己期待的审判图景。他差门徒去问：“那将要来的是你吗？”耶稣没有责备这个问题，而是让他们回去报告所看见的：瞎子看见、瘸子行走、穷人听见福音。', '耶稣用以赛亚式的医治与宣讲回答约翰，并称赞约翰是先知，却说明在神国里最小的也有新的位置。', '信心可以在牢房里发问；耶稣的回答不是抽象证明，而是指向正在发生的恢复。约翰伟大，却不能成为门徒停留的终点；神国已经临到，参与其中的人领受了约翰未曾看见的完整图景。', '监牢中的等待会放大人与现实之间的落差。耶稣引用赛 35:5–6、61:1 的意象，却没有在当时立刻执行所有审判，这让“按神时间等候”成为真实张力。“这一世代”拒绝约翰和耶稣的方式，也反映群体对先知性呼召的抗拒。', '可对照赛 35:5–6、61:1–2、玛 3:1；路 4:18–21、太 11:2–6 和雅 5:7–11 都帮助我们在未完全看见时持守盼望。', '讨论：当神没有照我期待的方式工作，我还愿意看见祂已经做成的什么？操练：写下一个未解决的问题，同时列出三件真实发生的恩典，不用它们互相抵消，而是带着两者一起祷告。'),
    n('7:36–50', '在桌边被赦免的女人', '法利赛人西门请耶稣吃饭，却没有给祂水、亲嘴和膏油的接待礼。一位被城里人称为罪人的女人进来，站在耶稣脚边哭，用眼泪湿了祂的脚，又用头发擦、用香膏抹。屋里每个人都在看她，耶稣却看见她的爱。', '耶稣以两个欠债人的比喻说明：那多得赦免的，爱也多；祂宣告这女人的罪赦了，并让她平安离开。', '耶稣不是说罪不重要，而是揭露西门以为自己不需要被赦免。女人的行动不是用爱换取赦免，而是从被接纳、被赦免中流出的爱；耶稣让她恢复成为能开口、能爱、能离开的人。', '筵席中的脚、亲吻与膏油属于待客与尊荣的语言；女人的身份在叙事中被模糊，却被“罪人”标签公开定义。关于她是否就是别处出现的马利亚，文本没有说明，不应把不同人物强行合并。', '可对照撒下 12:1–7、诗 51、何 6:6；约 13:1–17、路 15:20–24 继续展开主主动洁净、接纳和恢复人的爱。', '讨论：我们在教会里是更像被赦免后感恩的人，还是更像站在门口评估别人配不配进来的人？操练：向一个曾被你用标签定义的人，承认自己的判断，并以持续而非一次性的尊重重建关系。'),
  ],
  8: [
    n('8:1–3', '跟随耶稣的妇女也成为供给者', '耶稣走遍各城各乡传讲神国，十二门徒同行，几位曾被医治、被释放的妇女也在队伍中。马利亚、约亚拿、苏撒娜和许多别人用自己的财物供给他们；在一个常把公共宗教行动写成男性故事的时代，她们被路加清楚写进差遣队伍。', '一群妇女跟随耶稣，并用自己的资源支持祂和门徒的宣讲。', '她们不是被动接受帮助后退到背景，而是成为使命的参与者。被医治的经历转化为供给、同行和见证；教会的事奉不应只承认台前讲道，也要看见维持群体、承担当下需要的忠心。', '古代妇女的财产权、家庭地位因婚姻和阶层而异，不能用一个简单模型概括；约亚拿与希律家管事苦撒的关系显示，福音也进入宫廷和资源网络。路加把女性见证者反复放在重要位置。', '可对照王下 4:8–10、罗 16:1–7、腓 4:2–3；路 24:1–11 更会让这些妇女成为复活清晨的第一批见证者。', '讨论：我们怎样辨认并尊重那些不在台前、却使群体能够继续前进的人？操练：具体感谢一位长期承担隐形劳动的人，并把一项资源、决定权或表达空间真正交给他。'),
    n('8:4–15', '种子落在不同的土里', '耶稣对着从城镇聚来的大群人讲一个农夫撒种的故事。听众熟悉田地、路旁、石头和荆棘，却未必愿意承认自己也可能是其中任何一种土。种子相同，差异出现在它落下之后发生了什么。', '种子是神的道；不同土壤代表人听道后因魔鬼、试探、今生思虑、钱财或忍耐而有不同回应。', '比喻不是把人永久分类，而是邀请人检查“我怎样听”。好土不是天生比较优越，而是持守、忍耐并结出果实；果子需要时间，不能用一次热情的回应取代持续的生命。', '巴勒斯坦农作常先撒种后翻土，路旁、浅土和荆棘都是真实田地经验。耶稣解释比喻时把撒种者、种子、土壤和时间都保留，说明天国的道会遇见抵挡，却不会因此失去生命力。', '可对照赛 55:10–11、耶 4:3、申 30:11–14；雅 1:21–25 与可 4:1–20 提醒我们，听见道需要存温柔的心并实行。', '讨论：现在最像哪一种土壤的不是“别人”，而是我的哪一部分？操练：连续两周固定读同一小段经文，记录它揭露了什么、安慰了什么、要求你做什么。'),
    n('8:16–25', '灯要放在灯台上，船上却仍会有风暴', '房间里点灯的人不会把灯藏在器皿下；耶稣又转到湖面，一阵风暴使门徒慌乱。耶稣睡着了，门徒以为自己快要沉没，叫醒祂后，祂斥责风浪，也问他们的信心在哪里。', '听见神道的人要让它显明；耶稣平静风浪，显出祂对受造界的权柄，门徒却还在问“这到底是谁”。', '“隐藏的事没有不显出来”首先关乎真理终将被显明，不是鼓励人追逐曝光。风浪中，耶稣的同在没有立即消除恐惧；祂先让门徒面对自己对祂身份的认识。信心不是没有风，而是在风中重新问“主是谁”。', '加利利湖受地形影响，突发强风在历史与地理上是可能的；故事也承接旧约只有神掌管海和风的意象。门徒坐船同行，说明跟随主并不保证免于危险。', '可对照诗 107:23–29、诗 89:9、约伯 38:8–11；可 4:35–41、路 9:18–20 共同把“祂是谁”放在门徒成长中心。', '讨论：我们遇到风暴时最先问的是“谁来负责”，还是“耶稣此刻与我怎样同在”？操练：为一个令你失控的现实画出“我能做的、我不能做的、我可以交托的”三圈。'),
    n('8:26–39', '湖东墓地里，一个人重新穿上衣服', '船抵达湖东一带，耶稣遇见一个住在坟茔、被锁链也无法约束的人。他赤身、喊叫、远离群体；耶稣问他的名字，回答却是“群”。当污鬼离开，村民看见那人穿着衣服、心里明白，坐在耶稣脚前。', '耶稣释放被群鬼辖制的人；他想跟随耶稣，耶稣却差他回家述说神为他所做的大事。', '耶稣的拯救恢复一个人的名字、身体、心智和关系，而不是只完成一次属灵对抗。村民更害怕失去秩序和经济利益，故事没有美化他们；被释放的人则从“逃离家乡”转为“回家作见证”。', '湖东地区有外邦人居住的可能，猪群与墓地都强化了礼仪和文化边界。关于“群”的人数与地理位置，不必建立在每个细节的猜测上；文本重点是人在污秽、暴力和隔绝中的全面恢复。', '可对照赛 65:1–5、诗 107:10–16；路 4:18、约 8:36 与徒 16:16–18 继续说明基督释放人，不把人永远交给黑暗标签。', '讨论：我们是否把一个人的创伤、疾病或成瘾当成他的名字？操练：在安全和专业支持的前提下，陪伴一个被标签化的人恢复日常能力；不要用“见证”取代治疗和边界。'),
    n('8:40–56', '两种等候，在同一件衣裳上相遇', '耶稣回到加利利，人群围住祂。睚鲁来求祂救快死的女儿；耶稣前往途中，一个患血漏十二年的女人在人群后面摸祂衣裳繸子。一个有会堂领袖身份，一个长期因病被隔离；耶稣停下来，让隐藏的触摸成为公开的恢复。', '耶稣医治血漏妇人，又使睚鲁的女儿起来，称她为“闺女”，并叫人给她吃东西。', '耶稣没有让急迫的请求吞没慢性病人的需要，也没有让慢性病人的故事取消孩子的危机。祂称妇人为“女儿”，称小女孩为“孩子”，把两个被恐惧定义的人重新放回关系与日常饮食中。', '血漏使人可能处在利 15 所说的礼仪不洁净状态，十二年的病带来长期经济和社会耗损；会堂领袖则拥有公共身份。死亡在古代带来洁净张力，耶稣触摸死去的孩子，却使生命临到。', '可对照利 15、王下 4:32–37、可 5:21–43；来 11:1、12:1–3 也帮助我们把“忍耐等候”理解为在未看见完全结果时仍仰望主。', '讨论：小组里谁的急迫最容易被听见，谁的慢性痛苦最容易被忽略？操练：为一位长期承受疾病、照护或孤独的人安排持续的陪伴，而不是只在危机当天问候。'),
  ],
  9: [
    n('9:1–9', '被差遣出去，也要依靠接待', '十二门徒被叫到耶稣面前，祂给他们能力和权柄，差他们去传神国、医治病人。他们不能带面包、钱、备用衣服，只能进入一户人家，接受接待；被拒绝时也要离开，把尘土跺下。', '耶稣差遣十二人以简朴、依靠和清楚见证传讲神国；希律听见这些事，心里困惑耶稣是谁。', '差遣同时包含权柄和脆弱：门徒有能力，却没有把安全感装进行李。福音不是一项个人品牌，乃是被差的人进入别人家、接受关系、承受拒绝，并把焦点留给神国。', '“一无所带”是训练门徒不靠资源制造权威；接待在古代旅行和宣教中是基本生存条件。跺尘土表达关系断裂和见证完成，不是鼓励门徒以轻蔑对待不信者。', '可对照王上 17:8–16、申 8:2–5；路 10:1–12、徒 13:51、林前 9:14 又分别展开差遣、接待与供应的张力。', '讨论：我们服事时最依赖什么装备、预算或形象？操练：以一个小而可持续的方式去服事，不先准备完美方案，先进入一段真实关系并学习接受帮助。'),
    n('9:10–17', '在旷野，耶稣让门徒分发饼', '门徒回来，耶稣带他们退到伯赛大附近；群众却跟上来。天色渐晚，门徒想让人散开买食物，耶稣却说：“你们给他们吃吧。”五个饼、两条鱼在门徒手里显得太少，但在耶稣祝谢、擘开、交给他们之后，众人都吃饱。', '耶稣在旷野喂饱五千人，门徒从“请众人走”转为参与分发神所赐的供应。', '神迹的重点不只是数量，而是耶稣把门徒的不足纳入祂的怜悯。众人先被接纳、教导和医治，然后被喂饱；属灵与身体需要没有被人为分开。门徒不是供应的源头，却必须亲手把饼递出去。', '旷野、群众、十二篮子和五饼两鱼会让人想起出埃及、以利沙喂饱百人（王下 4:42–44）和神在旷野赐粮。路加没有交代每个人如何坐下的所有细节，重点是有秩序地让众人领受。', '可对照出 16 章、王下 4:42–44、诗 78:23–29；约 6 章把这件事放进“生命的粮”的长篇解释中。', '讨论：面对群体真实需要，我们是否很快说“这里没有足够资源”？操练：列出小组已有的五个饼和两条鱼——时间、技能、空间、关系、金钱——并决定一项共同分享的行动。'),
    n('9:18–27', '你们说我是谁', '耶稣独自祷告后问门徒：众人说我是谁？答案很多；祂再问：“你们说我是谁？”彼得回答是神所立的基督。紧接着耶稣讲受苦、被弃绝、被杀和复活，并说门徒若要跟从，也要天天背起十字架。', '彼得认出耶稣是基督；耶稣重新定义基督的道路，也重新定义门徒的跟随。', '正确称呼耶稣的名字，不等于已经明白祂的道路。门徒期待荣耀，耶稣先谈受苦；十字架不是偶尔的英雄牺牲，而是天天放下自我中心、忠于神并承担爱的代价。', '“基督”是受膏者、以色列盼望中的君王，不是一个抽象宗教姓氏。罗马十字架是羞辱、刑罚和帝国威慑的工具；耶稣把它转成忠心与救赎的道路，却没有把痛苦本身神圣化。', '可对照诗 2、赛 52:13–53:12、但 7:13–14；腓 2:5–11、彼前 2:21–25 说明荣耀与受苦在基督里相连。', '讨论：我期待的耶稣，是否只会帮助我成功，不会挑战我的控制？操练：本周在一个需要牺牲时间、面子或便利的选择上，具体实践一次“为了爱而放下自己”。'),
    n('9:28–36', '山上荣光与出埃及的谈话', '耶稣带彼得、约翰、雅各上山祷告。祂祷告时面貌改变，衣服发光；摩西和以利亚出现，谈论祂将要在耶路撒冷完成的“出埃及”。门徒半睡半醒，只看见荣光，却还没有完全听懂谈话的方向。', '耶稣在变像中显出荣耀；摩西和以利亚见证祂将要在耶路撒冷受死、复活并成就新的出埃及。', '荣耀没有把十字架取消，反而解释十字架。父神的声音叫门徒听耶稣，而不是把摩西、以利亚与耶稣并列成三个导师；门徒需要从山上回到山下，跟随一位走向耶路撒冷的主。', '山是启示、律法和先知相遇的场所；摩西和以利亚分别代表律法与先知，也都曾在山上经历神显现。路加独有“出埃及”一词，显示耶稣将完成的不只是离开苦难，而是通向新的约与生命。', '可对照出 24:15–18、王上 19:8–18、玛 4:4–6；彼后 1:16–18、约 1:14 继续见证基督的荣耀与可信。', '讨论：我们想停留在“属灵高峰”多久，才愿意回到需要照顾、冲突和受苦的现实？操练：把一次聚会中的感动翻译成一个山下行动：探访、道歉、承担或服事。'),
    n('9:37–50', '门徒争大，孩子却站在中间', '山下的人群混乱，一个父亲求耶稣救被鬼附的儿子；门徒却赶不出来。耶稣医治孩子后，门徒开始争论谁为大。祂把一个小孩放在身边，说接待这样的人就是接待祂；又提醒不要禁止不与他们同走的人。', '耶稣在释放受苦的孩子后，教导门徒以最小的为大，并拒绝把神的工作圈成自己的团队。', '门徒的权力竞争与孩子的脆弱形成刺眼对比。真正的伟大不是掌握更多平台，而是把自己放在受忽略者旁边；“不敌挡你们的就是帮助你们”也纠正属灵垄断，神的工作不受我们的品牌管理。', '古代儿童在社会权力上很低，不等于没有价值；耶稣用孩子作象征，强调接待无权势者。赶鬼失败也提醒门徒：曾经成功的经验不能取代持续依靠与祷告。', '可对照民 11:26–29、可 9:33–41、腓 2:3–4；雅 3:13–18 让我们看见争竞与从上头来的智慧彼此相反。', '讨论：我们是否更在意谁被看见，而不是谁正在受苦？操练：下一次小组中，主动把发言空间让给平常沉默的人，并在事后确认他是否真的被听见。'),
    n('9:51–62', '耶稣定意面向耶路撒冷', '从这一刻起，路加把镜头固定在耶路撒冷的方向。撒玛利亚村庄不接待耶稣，雅各和约翰想叫火从天降下；耶稣责备他们。有人想跟随，却被提醒没有枕头的地方；有人想先回家告别，耶稣用犁地的比喻谈跟随的专一。', '耶稣定意走向受死与复活的耶路撒冷；祂拒绝报复，也说明跟随祂需要优先次序。', '使命的坚定不等于对拒绝者的暴烈。耶稣既不降低跟随代价，也不允许门徒用“为主大发热心”掩盖报复欲。犁地需要向前看，不是轻视家庭，而是让神国的呼召成为最高忠诚。', '撒玛利亚人与犹太人之间有长期历史、宗教和地域张力，但不能把每个村庄或每个人都写成同一种敌意。古代旅行者依靠村庄接待，拒绝接待会真实影响行程；耶稣选择绕过报复继续前行。', '可对照王下 1:9–16、申 6:4–5、王上 19:19–21；路 14:25–33、腓 3:13–14 继续解释门徒的优先次序。', '讨论：我们有没有把拒绝当作报复的许可证？操练：面对一个不接受你信仰或意见的人，练习尊重离开、不说伤人的话，同时守住自己真正的委身。'),
  ],
  10: [
    n('10:1–20', '七十（二）个人被差遣', '耶稣在前往耶路撒冷的路上，又差遣一批门徒到祂将要到的各城各地。祂让他们两个人一组，像羊进入狼群；他们不能先把安全、资源和结果都安排好，只能带着平安进入一家一户。', '主差遣七十（二）个人传讲神国、医治病人；他们回来因鬼服了而欢喜，耶稣却把喜乐的根基放在名字记在天上。', '差遣的重点不是属灵能力带来的兴奋，而是奉主名进入真实邻舍。门徒会遇见接待，也会遇见拒绝；他们可以欢喜，却不能把成功当作身份。最深的安全不是“我很有能力”，而是“我属于神”。', '古抄本在人数上有七十或七十二的异文，反映早期抄本传统差异；这不改变段落的核心：耶稣扩展差遣，使万国的象征视野浮现。收割、工人、平安和尘土都是当时乡镇旅行可理解的图像。', '可对照创 10 的列国名单、民 11:16–30 与赛 52:7；路 9:1–6、徒 13:51，以及启 3:5 都把“差遣、见证、名字”连在一起。', '讨论：我们的服事喜乐，是来自被需要、成功，还是来自属于主？操练：两人一组，在未来两周为一个具体社区或邻舍制定一次“带着平安进入”的行动，行动后分享真实结果。'),
    n('10:21–24', '小孩子看见，聪明人可能错过', '门徒回来报告经历，耶稣被圣灵感动而欢喜。祂向父祷告：天国的奥秘向聪明通达人隐藏，向婴孩显明；随后转向门徒，说他们看见了许多先知和君王想看却没有看见的事。', '耶稣以感谢回应父的主权，并指出认识父与子的关系不是靠自我优越，而是领受启示。', '“婴孩”不是赞美无知，而是描述一种不靠地位掌控真理、愿意领受的姿态。门徒的特权不是用来骄傲，而是让他们更谦卑地知道自己正在参与先知和君王所盼望的救赎时刻。', '古代“聪明”常与受教育、地位和解释权相连；路加不反对思考，而是反对用知识把自己放在恩典之上。圣灵在路加福音中常把人的欢喜、祷告和使命连接起来。', '可对照诗 8:2、赛 29:14、但 2:20–22；林前 1:18–31 和彼前 1:10–12 进一步说明福音既超越人的智慧，也成全先知盼望。', '讨论：我们最难承认自己“不知道”的是哪一类问题？操练：读一段熟悉经文时，先写下一个你从未认真问过的问题，并听一位不同背景的信徒如何理解。'),
    n('10:25–37', '谁是落在路旁的邻舍', '耶路撒冷下耶利哥的路上，一个人被强盗剥去衣服、打个半死。祭司和利未人看见却从另一边过去；一个撒玛利亚人来到，动了慈心，包裹伤口、倒油和酒、把他带到店里，还预付费用。', '耶稣把“谁是我的邻舍”反转成“谁成为受伤者的邻舍”，并命令人照样去行。', '比喻没有先让受伤者证明自己值得帮助；邻舍是一个正在我面前受苦的人。慈心最终变成靠近、触摸、付费、安排后续，而不是一句“愿你平安”。撒玛利亚人的身份让听众无法用族群偏见轻易接受这个榜样。', '山路险要、旅店和油酒都符合古代旅行场景；祭司和利未人的具体顾虑经文没有说明，不能替他们编造动机。撒玛利亚人与犹太人之间有深刻的历史与宗教张力，所以耶稣选择他作施怜悯者，正面冲击群体边界。', '可对照利 19:18、代下 28:9–15、何 6:6；雅 2:8–17、约壹 3:16–18 把“怜悯邻舍”落在时间、风险和资源上。', '讨论：我们通常把谁排除在“我的邻舍”之外？操练：学习急救、陪诊、危机转介或社区资源，让你的怜悯具备可以持续的具体能力；遇到危险时也要先确保安全并求助。'),
    n('10:38–42', '忙乱的家里，主脚前的一席', '在一个村庄的家里，马大忙着预备接待，马利亚坐在主脚前听道。马大不是不爱主，而是被许多事务拉扯，最后带着委屈来请耶稣评理。耶稣温柔地指出她被许多事烦扰，马利亚选择了那上好的部分。', '耶稣肯定在祂脚前聆听的门徒姿态，不让服事变成控告别人或证明自己的方式。', '这段不是把听道和服事对立，也不是给忙碌者增加罪疚；问题在于“许多的事”夺走了中心，使马大无法再从爱中服事。马利亚坐在教师脚前，正是门徒学习的姿态，女性也被放在受教者的位置上。', '古代待客需要大量准备，厨房与接待工作往往由女性承担；路加没有贬低这份劳动，却揭露它在没有聆听和共同承担时会变成怨言。路加没有在这里明说村庄的名字；后来的传统常把它与伯大尼联系起来，约翰福音也把马大、马利亚的家庭放在伯大尼，因此应把“伯大尼”视为合理推断，而非路加此处的明确地点。', '可对照申 6:4–9、诗 27:4、徒 22:3；约 12:1–8 与路 9:57–62 继续思考“在主脚前”如何同时带来敬拜和行动。', '讨论：我的服事是否正在产生怨恨，因为我没有停下来领受？操练：在一次忙碌前先安排短暂的聆听与分工，明确哪些事情可以不做，避免用牺牲感控制别人。'),
  ],
  11: [
    n('11:1–4', '主啊，教导我们祷告', '耶稣在一个地方祷告完，门徒看见祂与父之间的关系，就来请求祂教导祷告。祂没有先给一套让人操控结果的公式，而是先让门徒称神为父，求祂的名被尊为圣、国度来到，再把每日饼、赦免和试探带进同一段祷告。', '主祷文把神的名、神的国、日用饮食、罪得赦免和在试探中的保守放在同一幅生活图景里。', '祷告先把“我想要什么”放回“神是谁、神的国是什么”。赦免既是领受也是实践，日用饮食说明门徒不是靠属灵姿态逃离身体需要；“不要叫我们遇见试探”则承认跟随者需要持续保守。', '犹太人已有以神为父、尊神名和盼望国度的祷告传统；耶稣使用门徒熟悉的语言，却以“父”带出亲近与信靠。路加的版本较短，与马太 6 章的版本有差异，显示这是教导祷告方向，不是念法本身。', '可对照出 34:6–7、诗 103:8–13、但 2:44；太 6:9–13、罗 8:15–17 与来 4:16 让我们看见儿女身份、赦免和坦然来到父前。', '讨论：我们祷告时最容易跳过哪一项——神的名、他人的饼、赦免，还是求保守？操练：把主祷文分成五天，每天用一项为自己、家庭和城市写出具体祷告。'),
    n('11:5–13', '半夜敲门的朋友', '夜里，朋友突然来到，一个人家里没有食物可以招待。他只好到邻舍门口不停敲门；屋内的人已经上床，孩子也在身边。耶稣说，即使不是因为朋友关系，也会因他一直求而起来给他。', '耶稣用半夜求饼的比喻鼓励门徒祈求、寻找、叩门，并以父亲给孩子好东西说明神更愿意赐圣灵。', '祷告不是把神磨到心软，也不是用次数换取答案；门徒被邀请以大胆、不顾情面而持续的姿态来到父面前。这里的“恒切”也可理解为不因羞耻和不便而退缩的大胆请求。比喻最后把焦点从饼推进到圣灵：神给的最好礼物不只是解决一件事，而是祂自己与我们同在。', '古代地中海家庭常同室睡眠，夜里开门会打扰全家；接待旅人是重要社会责任。第 8 节的希腊词可译作“恒切、无羞地坚持或大胆”，存在翻译和解释讨论；因此重点不是建立一套用重复次数操控神的祷告技巧。', '可对照创 18:1–8、出 16:4、撒上 1:9–18；罗 8:26、路 18:1–8 继续说明圣灵帮助软弱者，祷告需要坚持而非操控。', '讨论：我停止祷告，是因为神没有回应，还是因为我害怕再一次失望？操练：为一个长期代祷事项找一位同伴，每周一次简短报平安，不用制造属灵成绩。'),
    n('11:14–28', '神的国临到，谁才是真正有福', '一个哑巴被鬼赶出后开口说话，群众惊讶，却有人说耶稣靠鬼王赶鬼。耶稣指出，一个国若自相纷争就站立不住；祂又说自己若靠神的能力赶鬼，神的国就临到他们了。有人称赞怀祂的母亲，耶稣把有福转向听神之道而遵守的人。', '耶稣以赶鬼显明神国已经进入人的捆绑处境；真正的有福在于听道并遵行。', '人会把释放解释成威胁，因为神的国会动摇既有控制。耶稣不让人停在围观神迹，而是要求决定：不是与祂同在，就是敌挡；不是收聚，就是分散。这里首先是对面对耶稣、拒绝神国者的呼召，不应被用来把教会内部一切正常的分辨和意见差异贴成敌我。属灵经验若不转成顺服，仍可能成为旁观。', '古代对鬼王、驱邪和能力来源有不同解释；耶稣用“分裂的国”指出指控的逻辑问题。清扫干净的房屋比喻警告：空出来不等于被更新，生命需要让神的灵和道住进来。', '可对照出 8:7–9、诗 68:18、赛 49:24–25；太 12:22–32、雅 1:22–25 继续说明释放、归属与实行。', '讨论：神要更新我的哪一处控制时，我可能会把更新误读成威胁？操练：在戒掉一个坏习惯时，同时建立一个新的祷告、团契和服务节奏，不只靠意志留下空房子。'),
    n('11:29–36', '约拿的记号与身体里的光', '人群越来越大，大家要耶稣给一个从天上来的神迹。耶稣却说这世代只得到约拿的记号；南方女王和尼尼微人将来要成为见证。祂又说眼睛是身体的灯：若眼睛明亮，全身就光明。', '耶稣拒绝把神迹当作满足好奇的凭证，呼召人回应比约拿和所罗门更大的自己，并警告要检查里面的光。', '问题不总是证据太少，也可能是人不愿悔改。尼尼微人听约拿就悔改，南方女王为听所罗门而来；耶稣在场却被要求不断证明。属灵“光”不仅是知道更多，而是让整个人被真理照亮。', '约拿故事与南方女王分别来自先知传统和列王纪传统；路加把外邦人的回应放在以色列拒绝旁边，形成尖锐对照。“约拿的记号”在平行经文中与死亡、复起和宣讲有关，解释时应保持谦慎。', '可对照拿 3:5–10、王上 10:1–10、诗 119:105；太 12:38–42、约 1:4–9 与弗 5:8–14 都把光连接到悔改和生活。', '讨论：我是否不断要求新证据，却忽略已经听见、已经知道的顺服？操练：选一项已经明确的圣经教导，停止继续搜集意见，做一个可被检验的行动。'),
    n('11:37–54', '饭桌上的洁净与里面的公义', '一个法利赛人请耶稣吃饭，先惊讶祂没有按仪式洗手。耶稣把外在杯盘与里面的贪婪、公义、爱神放在一起，随后向法利赛人和律法师发出多重“祸”。屋内从一顿饭变成一场关于领导责任的审判。', '耶稣指出宗教外表若遮盖贪婪、忽略公义和妨碍人认识神，就会成为重担而非帮助。', '耶稣的严厉不是针对每个仪式本身，而是针对用敬虔外观掩盖权力和冷漠。祂也警告读经与教导者：你们把难担的担子放在人身上，自己却不肯动一根指头。', '法利赛人的洁净传统重视餐前礼仪，律法师负责解释律法；路加没有把他们写成单一恶人，而是让耶稣指出宗教权威最危险的失败：让别人更难靠近神。', '可对照赛 1:10–17、弥 6:8、摩 5:21–24；太 23 章、雅 3:1 与罗 2:17–24 都把外在教导者置于更高责任下。', '讨论：我们的属灵语言是否让新朋友更接近神，还是只让他害怕犯错？操练：审核小组的一项要求、表格或惯例，删去不能帮助爱神爱人的负担，并补上实际陪伴。'),
  ],
  12: [
    n('12:1–12', '在众人面前不必假冒', '几万人聚集，甚至彼此践踏；耶稣先对门徒说要防备法利赛人的酵，就是假冒为善。祂没有给门徒一套隐藏恐惧的方法，而是说那杀身体的不要怕，要敬畏神；又应许圣灵在受审问时教导他们当说的话。', '耶稣呼召门徒在压力与逼迫中诚实见证，不隐藏、不否认，也相信父看见每一只麻雀和每一根头发。', '假冒是里面和外面分裂；福音却把隐藏处带到光中。耶稣既承认逼迫的危险，也不让恐惧成为最终主人。承认基督不是表演勇敢，而是在圣灵帮助下说真实的话。', '古代宗教与政治权力交织，公开承认某种“主”可能具有社会风险；麻雀是低价值小鸟，头发则是个人最细微的部分。耶稣用这些图像说明父的看顾不是抽象概念。', '可对照诗 56:3–4、赛 8:12–13、但 3:16–18；太 10:26–33、徒 4:8–20 与彼前 3:15–16 继续谈见证与受压。', '讨论：我在哪些场合最容易为了合群而隐藏信仰或扭曲事实？操练：预备一句温柔、清楚、不攻击人的信仰表达，在下一次真实对话中使用，而不是等到危机才临时编造。'),
    n('12:13–21', '仓房越来越大，灵魂却没有安息', '人群中有人请耶稣替他向兄长分家产。耶稣拒绝成为财产仲裁者，却转向所有人讲一个富足人的故事：田产丰盛，仓房不够，他拆了重盖，终于对灵魂说可以安逸，却在当夜失去生命。', '人的生命不在乎财物多少；只为自己积财、在神面前不富足的人，正是无知的财主。', '耶稣没有说储蓄、经营或丰收本身是罪，问题是财富把未来完全锁进“我的仓房、我的粮食、我的安逸”。死亡揭开一个事实：人可以拥有很多，却没有把生命交给神，也没有让财富成为爱邻舍的工具。', '古代农业社会的土地、粮仓与家族继承关系紧密；分家争议可能牵涉家庭权力。比喻中“我的”反复出现，突出财主把丰收当成完全私人化的成果，忘记土地、天气、工人和神。', '可对照申 8:10–18、传 5:10–15、箴 11:4；提前 6:6–19、雅 5:1–6 与路 16 章继续把财富置于永恒和邻舍关系中。', '讨论：我目前的财务目标，是为了更深地爱人，还是为了把不安藏进更大的仓房？操练：把一次收入或储蓄计划分出明确比例，用于慷慨、公共需要或帮助一个具体家庭。'),
    n('12:22–34', '不要忧虑，先求祂的国', '耶稣从财主的仓房转向门徒的饭桌和衣柜：不要为生命忧虑吃什么、身体穿什么。祂让他们看乌鸦、百合和田野的草，也承认小群会害怕，便应许父乐意把国赐给他们。', '门徒不以忧虑作为生活主轴，而是先求神的国，把财物变成施舍和天上的财宝。', '“不要忧虑”不是否认饥饿、失业、疾病和责任，而是拒绝让不确定性成为主人。耶稣在这里向门徒提出具体而激进的天国道路：先求国、变卖周济、预备不会朽坏的财宝；这不是对每个人发出同一种财务操作指令，却要求所有人让心和资源接受神国审判。', '乌鸦和百合是耶稣身边常见的受造物；古代社会没有现代社会保障，衣食忧虑更为真实。对“小群”的称呼不是否定弱小，而是用牧者语言安慰一个在压力中等待国度的群体。', '可对照诗 55:22、箴 3:5–6、王上 17:1–16；太 6:25–34、腓 4:6–7、彼前 5:7 都把忧虑带到父的看顾中。', '讨论：在实际预算与责任之外，我还在用什么方式喂养忧虑？操练：建立一个“先求国”的月度安排：固定奉献或分享、固定祷告、固定关怀，并以诚实预算配合，而非冲动承诺。'),
    n('12:35–48', '腰里束带，等候主人回来', '夜里的房屋里，仆人点着灯，等候主人从婚宴回来。主人什么时候回来并不确定；有的仆人警醒，主人回来反而亲自束带服事他们；有的仆人趁主人迟延就欺压同伴。', '耶稣以仆人和管家的比喻教导门徒警醒、忠心，并按所领受的责任承担更多责任。', '警醒不是焦虑计算日期，而是在主人似乎迟延时仍按祂的心意生活。真正的权柄表现为照料同伴；“多给谁，就向谁多取”把属灵特权转成责任，不许领袖用等待主回来作为压迫别人的借口。', '婚宴夜归、灯火、家仆和管家都是古代家庭场景；主人亲自服事仆人是反转性的图像，预示耶稣在最后晚餐为门徒服事。经文没有给末日时间表，而是给群体伦理。', '可对照出 12:1–2、但 12:1–3、太 24:42–51；约 13:1–17、彼前 5:1–4 说明主所喜悦的领导是牧养，不是辖制。', '讨论：如果主今天回来，我最希望祂看见我正在照顾谁？操练：把一个你拥有的职位、知识或资源，转成对较弱者的保护和培育，而不是只用于证明自己重要。'),
    n('12:49–59', '读懂这时候，却不逃避分裂', '耶稣说祂来要把火投在地上，也要面对尚未完成的洗；跟随祂会在家庭和社会中带来分裂。祂又用天气和诉讼的日常判断作比喻：人会判断云彩，却不会判断这个时机，不能一直拖到法庭门口才和解。', '耶稣的来临要求人作决定；门徒要辨认时代，并在仍有机会时主动与对头和好。', '福音带来平安，却不保证所有人会因此同意；真正的分裂来自忠于基督与旧有忠诚发生冲突。辨认时代不是猜测新闻，而是看见神正在呼召我们悔改、和好、站立。', '火、洗和分裂都带有先知性的审判与洁净意象；古代法律诉讼可能迅速带来监禁和财产损失，所以“还在路上就和解”是现实的智慧，不是廉价地要求受害者放弃安全或公义。', '可对照弥 7:5–7、珥 2:12–13、摩 3:6–8；太 10:34–39、罗 12:18、林后 5:18–20 一同平衡忠诚、冲突与和好。', '讨论：我是在用“和平”逃避该说的真话，还是用“真理”掩盖自己不愿爱人？操练：辨认一段需要尽快处理的关系冲突，在安全前提下先发出一则承担责任、约定对话的讯息。'),
  ],
  13: [
    n('13:1–9', '不要把别人的灾难当作优越的证据', '有人带来一个骇人的消息：加利利人的血被彼拉多混在他们祭物中。耶稣又提到西罗亚楼倒塌压死十八个人。众人想知道他们是不是比别人更有罪；耶稣把问题转向所有人：你们若不悔改，都要如此灭亡。', '耶稣拒绝用受害者的灾难证明他们特别有罪，却呼召所有人悔改，并以不结果子的无花果树说明神的忍耐。', '悔改不是对灾难幸灾乐祸，也不是把每一场事故解释成受害者个人的报应。耶稣承认死亡的严肃，又给出回转的时间；园丁松土、施肥，显示恩典会耐心工作，但耐心不是无限拖延的借口。', '当时人常以报应逻辑理解疾病和灾难；彼拉多是罗马总督，政治暴力可能发生在宗教场所，西罗亚楼倒塌则像今天的工程事故。经文没有说明事故原因，也没有把所有灾难归因于某人的隐藏罪。', '可对照伯 1–2、结 18:1–23、约 9:1–3；彼后 3:9、约 9:4 与路 19:41–44 共同呈现神的忍耐和悔改的紧迫。', '讨论：听见灾难新闻时，我第一反应是怜悯、恐惧、判断还是优越感？操练：为受灾者祷告并核实可靠的援助渠道，同时在自己的生活中处理一个已经知道却一直拖延的悔改行动。'),
    n('13:10–17', '被捆绑十八年的女人站直了', '安息日的会堂里，一个女人弯腰十八年，身体无法直立。耶稣看见她，叫她过来，按手在她身上，她立刻直起腰来赞美神。会堂主管却因“安息日医治”发怒，耶稣指出他们连牲畜都肯解开牵去喝水。', '耶稣称这女人为亚伯拉罕的女儿，在安息日释放她脱离长期捆绑。', '耶稣让一个被疾病和时间遮蔽的女性重新站在群体中心，并公开称她属于应许的家庭。安息日不是把人的痛苦锁得更紧，而是神释放受压者的日子；宗教秩序若看不见她，就需要被重新解释。', '古代疾病常被用属灵和道德语言解释，路加同时说她被撒但捆绑，却不允许读者因此责怪她。会堂主管代表礼仪边界，牲畜解缚的例子来自日常律法推理，突显对人的怜悯更应优先。', '可对照出 20:8–11、申 5:12–15、赛 58:6–14；路 6:6–11、加 3:7、29 进一步说明在基督里，女性也被称为亚伯拉罕的后裔。', '讨论：我们的制度是否让某些人一直弯着腰，却只在乎流程有没有被打破？操练：在小组或教会流程中找出一项让行动不便、照护者或新来者难以参与的安排，和当事人一起改进。'),
    n('13:18–21', '芥菜种与面酵：小得看不见的国', '耶稣没有用军队和宫殿解释神的国，而是拿起一粒芥菜种，又说妇人把面酵藏在三斗面里。种子长成树，面团全发起来；国度的工作从一个容易被忽略的起点开始，慢慢改变整团面。', '神的国起初似乎微小，却有从内部生长、扩展和改变整体的能力。', '小不是无关紧要，慢也不是没有神工作。两个比喻都强调隐藏的过程：人不能用即时可见的规模衡量神的国。门徒要学习忠心播种、调和、等待，而不是用焦虑把成长拉出来。', '芥菜在加利利是常见植物，树的说法带有夸张的比喻色彩；“三斗面”是很大的量，说明少量面酵可以影响整体。古代读者熟悉家庭烘焙和农业，不需要把比喻变成植物学说明。', '可对照结 17:22–24、但 4:10–12、创 18:6；太 13:31–33、林前 3:6–9、加 5:9 继续说明神国生长与群体更新。', '讨论：我们是否因为看不到规模，就否定一个小而忠心的开始？操练：选一项能持续两周以上的微小操练——每日一句祝福、一次倾听、一项慷慨——观察它如何影响关系。'),
    n('13:22–30', '窄门不是优越感的门', '有人问耶稣得救的人少吗？耶稣没有给人数统计，而是说要努力进窄门。有人以为自己吃过饭、听过教导就自然属于里面；门关上后，主人却说“不认识你们”。随后，原本被排在外面的人从四方来坐席。', '耶稣呼召人现在就回应神，不靠熟悉宗教场景或血统自称属于国度；神国的席位会翻转人的排名。', '“努力”不是靠功德赚得救恩，而是不要把回应无限推迟。与耶稣同桌、听过祂教导，却不让祂改变生活，仍可能是外在靠近。窄门也不是教会用来排斥别人的武器，因为末后的次序超出我们的判断。', '筵席和门的图像来自弥赛亚宴席与末世审判的传统；当时“我们是亚伯拉罕的子孙”是重要群体身份，耶稣却把真正的归属放在回应神的邀请上。', '可对照赛 25:6–9、创 12:3、诗 107:2–3；太 7:13–14、罗 9:6–8、启 7:9 都帮助我们理解窄门与万民聚集的张力。', '讨论：我是否把教会经历、家庭背景或服事资历，当成不必再悔改的凭据？操练：把一个“大家都知道我信主”的外在身份，落实成一项只有神看见的忠心行动。'),
    n('13:31–35', '母鸡翅膀下的耶路撒冷', '有人来警告耶稣希律要杀祂，祂却继续医治、赶鬼，并说先知不能在耶路撒冷之外被害。耶稣望向圣城，为它拒绝聚集而哀哭：祂愿意像母鸡聚集小鸡，城却不愿意。', '耶稣不被希律的威胁改变使命，并以母鸡的图像表达对耶路撒冷拒绝神、却仍深切怜悯的心。', '勇敢不等于没有眼泪；耶稣既不向暴君投降，也不以仇恨凝视拒绝者。祂的审判话语和母鸡翅膀下的渴望同时存在，说明神的警告本身也是爱的最后呼唤。', '希律安提帕掌管加利利，曾囚禁约翰；耶路撒冷则是圣殿、先知传统和国家盼望的中心。耶稣说“奉主名来的是应当称颂的”带有诗篇 118 的朝圣语言，预示进城。', '可对照申 32:11、诗 91:4、诗 118:26；路 19:41–44、太 23:37–39 与路 23:34 让我们看见审判与哀哭、赦免相邻。', '讨论：我面对拒绝时，是否只想证明对方错，却失去为对方哀哭的能力？操练：为一个与你意见不同的群体写一段不带讽刺的代祷，求神也改变你看他们的方式。'),
  ],
  14: [
    n('14:1–6', '在安息日看见一个人，而不是一场辩论', '安息日，耶稣到一个法利赛人的首领家里吃饭；众人盯着祂，那里有一个患水臌的人。耶稣先问律法教师和法利赛人，安息日治病可以不可以；他们沉默，耶稣便医治并让他走。', '耶稣在安息日医治病人，指出怜悯并不违反律法真正的目的。', '一个人的身体被放进一场宗教测试，耶稣把他从试题中心带回人的位置。祂用“儿子或牛掉进井里”说明人本来就知道危难中要施救，问题是我们是否只在看见同类时才应用怜悯。', '水臌是身体明显肿胀的病症，古代医学解释与现代不同；文本没有要求把病归咎于罪。法利赛人家中的宴席、安息日和观察者构成一场社会性审查，耶稣在公共场合恢复人的尊严。', '可对照何 6:6、弥 6:8、路 6:6–11；太 12:9–14、约 5:1–18 都把安息日争议落到具体身体和行动上。', '讨论：我们是否把需要帮助的人当成证明自己观点的案例？操练：在讨论争议议题前，先认识一个受影响者的名字和故事，让怜悯进入神学判断。'),
    n('14:7–14', '不要抢首位，邀请不能回报你的人', '宴席上，耶稣看见客人争坐首位，就讲婚筵上的座位；随后对主人说，不要只请能回请你的亲友和富足邻舍，也要请贫穷、残疾、瘸腿、瞎眼的人。', '耶稣把谦卑与慷慨放在同一张宴席上：不抢位置，也不以邀请换取回报。', '谦卑不是假装自己不重要，而是不把自己放在中心争夺尊荣；慷慨也不是投资人情，而是让不能回报的人进入我们的桌。复活时的赏赐不能被换算成今生的掌声，正因如此，善行可以不急着被看见。', '古代宴席座次体现社会等级，吃饭是建立互惠网络的重要方式。耶稣不是禁止家庭友谊，而是挑战一个只向上经营关系的系统，把公共尊荣重新给被忽略者。', '可对照箴 25:6–7、申 15:7–11、撒上 2:7–8；雅 2:1–9、罗 12:10、提前 6:17–19 把宴席伦理带入教会与家庭。', '讨论：我邀请人，是因为爱他，还是因为他能让我更体面？操练：安排一次不求回请、不拍照宣传的接待，邀请一个平常无法回报你的人，并尊重他的时间和选择。'),
    n('14:15–24', '被邀请的人一个个找理由', '有人听见耶稣讲宴席，便说“在神国里吃饭的有福了”。耶稣讲一个主人摆设大筵席的故事：牛羊已经预备，受邀的人却因田地、买牛和婚姻一一推辞。主人于是把邀请带到城里的贫穷人、残废人、瞎眼人和瘸腿人，甚至带到路上篱笆旁的人。', '神国的宴席已经预备，但自以为有优先权的人因现实牵挂拒绝；主人主动把邀请扩展给被排除者。', '拒绝不一定看起来邪恶，常以合理、忙碌和“以后再说”的方式出现。耶稣不是反对田地、牛和婚姻，而是揭露任何好东西都可能成为拒绝神的借口。恩典扩张到边缘处，正是因为主人坚持让屋子坐满。', '宴席邀请通常需要预先通知与临近时再次确认，临时推辞会带来社会羞辱；比喻中的“逼着进来”应理解为热切邀请，不是强迫或侵犯。末世宴席是犹太盼望的重要图像。', '可对照赛 25:6–9、箴 9:1–6；太 22:1–14、启 19:6–9 与路 13:28–29 展开邀请、拒绝和万民进入的主题。', '讨论：我现在用哪一个“合理安排”一直推迟回应神？操练：把一个持续拖延的属灵回应写进日历，邀请同伴陪你完成，而不是只增加更多感动。'),
    n('14:25–35', '背十字架之前先计算代价', '大群人跟着耶稣上路，热情正在增长。祂却转身告诉他们：跟随要面对家庭、自己、十字架和财物的重新排序；一个人盖楼会先计算，打仗的王会先估量兵力，盐若失味也没有用。', '耶稣不以人数取悦群众，而是呼召门徒在一切关系和所有权上把祂放在首位。', '“恨”在这里是强烈的比较性表达：与对基督的最高忠诚相比，其他关系必须退居其次；平行经文太 10:37 也用“爱父母超过我”帮助解释。它不是教导人虐待或切断家人。背十字架不是追求痛苦，而是在忠于主时愿意承担损失；计算代价反而保护跟随免于一时冲动。', '十字架在罗马世界代表公开羞辱和处决，听众不会把它当成装饰。这里的“恨”具有夸张和门徒呼召的语气，不能脱离上下文变成家庭控制或属灵操纵的凭据。楼房、军队和盐都是日常生活图像，说明门徒训练需要真实评估，而不是只靠聚会情绪。', '可对照申 6:4–5、王上 19:19–21、腓 3:7–8；太 10:37、路 9:23、加 2:20、来 12:1–3 继续解释舍己和忍耐。', '讨论：我愿意跟随主到哪一步，一旦影响金钱、家庭期待、声誉或便利就停下？操练：列出跟随基督目前需要你承担的一项真实代价，并与成熟信徒讨论怎样健康、负责地承担它。'),
  ],
  15: [
    n('15:1–7', '失羊的牧人把它扛回家', '税吏和罪人不断挨近耶稣听道，法利赛人和文士却议论祂接待罪人、又同他们吃饭。耶稣于是讲一个牧人有一百只羊却丢了一只的故事；牧人把九十九只留在旷野，去找那一只，找到后扛在肩上回家。', '天上为一个罪人悔改欢喜；神主动寻找失丧者，祂的喜乐也挑战宗教人的不满。', '比喻的重点不只是羊走丢，更是牧人的主动寻找和找到后的庆祝。耶稣没有把罪轻描淡写，而是把悔改描绘成被找回、被扛回群体的喜乐。九十九只“无需悔改”也可能是对自义者的反讽。', '牧羊是以色列熟悉的职业和领袖隐喻，羊群在旷野需要真实风险管理；比喻不是教会管理的完整政策。古代宴席和邻里分享会把个人找回变成共同体事件。', '可对照结 34:11–16、诗 23、赛 40:10–11；约 10:1–18、彼前 2:25 与路 19:10 都把耶稣写成寻找、保护和带回的人。', '讨论：我是否更关心“这只羊为什么走丢”，而不是先帮助它回到安全？操练：联系一位久未出现、可能孤单的人，先问候和聆听，不用责备或追问他为什么离开。'),
    n('15:8–10', '点灯、扫地、直到找回一枚钱', '一个妇人有十块钱，丢了一块。她点上灯，打扫屋子，仔细寻找；找到后请朋友邻舍来一起欢喜。金额不大，动作却不敷衍——她愿意让整间屋子为一件失而复得的小事亮起来。', '天使也为一个罪人悔改欢喜；神的寻找不按人的价值排序。', '这段把寻找者从牧人换成妇人，让我们看见神的形象不应被单一性别和职业限制。失去的那一枚钱不会自己回来；恩典是主动、耐心、细致的工作，找到后不是冷静记账，而是喜乐分享。', '古代家庭的硬币可能是日常生活储蓄、嫁妆或家庭资源的一部分，具体价值不能确定。屋内光线较暗，点灯和扫地是合理的寻找动作；故事用小事承载天上的欢喜。', '可对照番 3:17、赛 62:4–5、路 1:46–55；启 19:6–9 的婚宴欢喜与路 15 的庆祝彼此呼应。', '讨论：我们是否认为某些人的回转“小到不值得教会庆祝”？操练：为一个微小但真实的改变公开感谢神，避免只在重大突破时才给人鼓励。'),
    n('15:11–24', '父亲跑向回家的小儿子', '小儿子把父亲还活着就要的产业带到远方，很快耗尽；饥荒来临，他只能去放猪，连猪吃的豆荚也没有人给他。醒悟后，他预备一段认罪词，远远看见他的父亲就跑去抱住他，吩咐仆人拿袍子、戒指和鞋，摆设筵席。', '父亲主动迎接悔改的儿子，恢复他的身份；失而复得不是雇工回家，而是儿子回到父亲的怀中。', '儿子确实承认得罪父亲，但父亲的拥抱先于完整的补偿计划。袍子、戒指、鞋和宴席都是恢复尊严与家庭位置的记号；恩典不是说伤害没有发生，而是拒绝让失败成为这个人的最后名字。', '父亲在古代家长角色中主动奔跑、公开拥抱一个带来羞辱的儿子，具有反常的情感强度。猪对犹太听众是不洁意象，远方、饥荒和雇工身份把儿子的降落写到最低；比喻没有详细说明产业如何处理，焦点是父的心。', '可对照创 45:1–15、何 11:1–9、诗 103:8–13；林后 5:17–21、弗 2:13–19 把回转和与神、与群体和好连接起来。', '讨论：我更像正在回家的小儿子，还是那个不相信自己还能被接纳的人？操练：若你曾伤害人，在安全且不操控对方的前提下作出具体道歉与赔偿；若你是接纳者，学习恢复关系而不抹掉界限。'),
    n('15:25–32', '站在门外的大儿子', '大儿子从田里回来，听见音乐舞蹈，知道弟弟回来了，却不肯进屋。父亲出来劝他，他说自己多年服事却没有得到一只山羊，称弟弟为“你这个儿子”。父亲回答：你常和我同在，我一切所有的都是你的；只是这个弟弟是死而复活、失而又得的。', '父亲同时向离家的小儿子和留在家中、心却远离的长子发出邀请。', '长子的痛苦是真实的：忠心者也可能感觉被忽略。父亲没有否认他的付出，却拒绝让恩典变成零和竞争；弟弟被恢复，不等于长子失去所有。比喻停在门口，邀请听众决定是否进去。', '长子不进宴席会使父亲在宾客前失去尊严；父亲再次出门，显示他对两个儿子都主动。古代长子有继承与责任地位，但这份地位也可能变成计算功劳的牢笼。', '可对照拿 2:10、约拿 4:1–11、创 4:1–16；太 20:1–16、罗 9:30–33 帮助我们面对“别人得恩典为何令我不平”。', '讨论：哪一类人的蒙恩最容易让我觉得“不公平”？操练：把一次“我做了这么多却没人看见”的委屈诚实告诉神，也主动庆祝别人得到的好处，观察心里的竞争如何被医治。'),
  ],
  16: [
    n('16:1–13', '不义管家懂得为将来预备', '一个管家被主人发现浪费财物，即将失去工作。他没有力气挖地，又羞于讨饭，于是趁还掌管账目时减轻债户的欠款，换取将来有人接待。主人竟称赞他的机警；耶稣随即把话题转向门徒如何使用今世的钱财。', '耶稣不是称赞欺诈本身，而是指出这个管家面对危机时的机警，并要求门徒在不义钱财上忠心；主人究竟称赞了行动的哪一层面，以及账目具体如何被改动，历来有不同解释。', '比喻令人不舒服，正因它不能被简化成“做坏事也没关系”。较稳妥的读法是先承认故事的诠释困难，再观察耶稣明确的转折：门徒要像管家一样正视时间有限、为将来作准备，却不能把机警等同于欺诈。小事上不可靠的人，大事上也不会可靠。', '古代管家可能替主人管理债务、租金和物资，账目中包含手续费或分成的可能，但文本没有说明他改的是利息还是总额。耶稣的结论明确把财富称为“不义的钱财”，不是把商业机诈变成道德榜样；这段应作为财富与忠心的难题阅读，而不是现代投资或商业伦理的快捷答案。', '可对照箴 11:4、16:8–9、摩 8:4–6；路 12:13–34、提前 6:17–19 与路 19:11–27 继续谈财富、托付和忠心。', '讨论：如果我的钱、时间和专业都是受托的，我今天会怎样用？操练：做一份透明的资源清单，挑一项长期用于祝福别人，并邀请家人或同伴帮助你持续执行。'),
    n('16:14–18', '法利赛人爱钱，律法却指向神的国', '法利赛人听见这些话就嗤笑耶稣，因为他们贪爱钱财。耶稣说人所尊贵的，神看为可憎；从约翰以来神国传开，人人努力进入；天地要废去，律法的一点一画也不能废去。', '耶稣揭露金钱如何影响宗教判断，并说明神国的临到不是取消律法，而是把人带到律法真正的目标。', '耶稣不是说所有富人都虚假，而是指出金钱会让人把“看起来成功”当成神的认可。律法与先知到约翰，耶稣不是另造一套随意宗教；祂在应验中揭露人如何利用律法保护自己。', '“嗤笑”显出面对金钱批评时的防御。关于“人人努力进入”可含有迫切回应、遭遇强烈抵挡等多层意味，不能只变成靠行为赚取救恩。婚姻的简短教导也说明天国更新会触碰权力与忠诚关系。', '可对照诗 119:89–112、弥 6:8、玛 3:1；太 5:17–20、罗 3:31、雅 2:8–12 平衡律法的持久价值与在基督里的成全。', '讨论：当经文挑战我的金钱观，我会先解释经文，还是先让它审判我？操练：让一个可信任的人看见一项实际财务决定，讨论它是否同时符合诚实、公义与爱邻舍。'),
    n('16:19–31', '门口的拉撒路与餐桌上的财主', '一个财主每天穿紫色细麻衣，宴乐奢华；他的门口躺着一个浑身生疮、渴望桌上碎渣的拉撒路，狗来舔他的疮。两人死后，故事发生翻转：拉撒路在亚伯拉罕怀里，财主在痛苦中，终于第一次看见门外的人。', '耶稣以死后的反转警告：无视门口的贫穷就是拒绝摩西和先知；若不听经文，连死人复活也不能说服人。', '财主的罪不只是不捐款，而是他每天经过一个人却不让对方进入视野。“拉撒路”是本章唯一有名字的人，名字意为神帮助，表明神看见被富人忽略的人。故事的重点不是提供完整的来世地图，而是审判今生的冷漠。', '紫色衣服、细麻衣和每日宴乐显示极度奢华；狗在当时可能被视为不洁或城市流浪动物。亚伯拉罕怀中是安慰和亲密的图像；“摩西和先知”指向现有圣经见证，而不是等待额外奇观。', '可对照申 15:7–11、赛 58:6–10、摩 6:4–7；路 4:18–19、雅 2:14–17、徒 2:44–45 把听道与分享资源连接起来。', '讨论：我每天经过哪些“门口”，却已经学会不看？操练：做一次真实的邻舍地图，认识一位处在你生活边缘的人；用尊重和长期关系回应，而非把他当成一次性项目。'),
  ],
  17: [
    n('17:1–10', '绊倒人、饶恕人、相信神', '耶稣先对门徒说，绊倒人的事难免，但把软弱者带入跌倒的人有祸。门徒听见“每天七次得罪你又回来，说我悔改，就饶恕他”，便求主加增信心；耶稣用芥菜种和无用仆人的比喻回应。', '门徒要认真对待自己对别人的影响，持续饶恕，并承认忠心不是向神索取奖赏的功劳。', '饶恕不是否认伤害，也不是把受害者重新置于危险中；它拒绝让报复成为生命中心，同时需要悔改、界限和公义。芥菜种说明信心不是自我放大的感觉；仆人比喻则拆穿“我做了这些，神就欠我”的心态。', '古代师徒关系和仆人制度提供比喻背景，但不能把其中全部社会结构直接当作基督徒伦理。耶稣把群体中权力较大者的责任放在前面：不可利用自由伤害小子。', '可对照创 4:23–24、利 19:17–18、弥 6:8；太 18:6–35、弗 4:31–32 与西 3:12–13 把饶恕放进教会冲突处理。', '讨论：我需要的是饶恕、和好、界限还是专业介入？操练：把一段伤害关系分成“神前释放怨恨、对方需承担的责任、我需要的安全界限”三栏，避免用一句饶恕跳过真实处理。'),
    n('17:11–19', '十个人得洁净，只有一个回来', '耶稣走在撒玛利亚和加利利中间，十个长大麻风的人远远站着，高声求怜悯。耶稣叫他们去给祭司察看，他们在路上就洁净了；其中一个看见自己好了，转身大声归荣耀给神，俯伏在耶稣脚前感谢，且是撒玛利亚人。', '十人都得洁净，只有一个回来感谢；耶稣称他的信心使他得救，并指出外族人反而回来归荣耀给神。', '恩典可以先被领受，却未必都转化成关系和敬拜。撒玛利亚人的回转不是礼貌加分，而是承认救恩的源头、回到施恩者面前。耶稣也让我们看见，宗教边界之外的人可能成为真正回应的人。', '麻风病人必须与群体保持距离，并由祭司确认洁净后才能恢复社会与敬拜生活。撒玛利亚人与犹太人关系紧张，路加特意保留他的身份，打破“谁更懂得感谢”的预期。', '可对照利 13–14、王下 5:1–19、诗 103:1–5；路 7:9、10:33–37 与西 3:15–17 都把感恩与信心、共同体和日常生活连在一起。', '讨论：我把神的恩典当作服务台，领受后就离开，还是会回来建立关系？操练：每天写下一件具体恩典，并把感谢转成一个行动：归还、分享、道歉、陪伴或公开归荣耀给神。'),
    n('17:20–37', '神的国在你们中间，也会带来审判', '法利赛人问神的国几时来到。耶稣说神的国来到不是眼所能见的外在标记，神的国就在你们中间；随后祂把门徒带到挪亚、罗得和闪电的图像中，提醒他们人会照常吃喝买卖，却在审判临到时措手不及。', '神的国已经在耶稣的临在中来到，也将有完全显明的一日；门徒要警醒，不被日常安逸麻醉。', '“在你们中间”可理解为在耶稣这个王的临在中，或在群体当中；重点不是让人忽略未来，而是不要把国度推到只与未来有关。警醒不是四处寻找末日密码，而是在平常日子忠心，不回头抓住已经被神审判的旧生活。', '挪亚和罗得的故事来自创 6–19，强调审判前人仍在日常安排中。人子日子的具体时间与“尸首、鹰”的图像有解释差异，不能用它制造恐慌式日历；经文清楚要求的是辨认和忠心。', '可对照创 6:5–13、19:15–26、但 7:13–14；路 21:29–36、帖前 5:1–11、彼后 3:10–14 继续谈盼望与警醒。', '讨论：我的日常安排中，哪些事让我以为“神的国还没来”？操练：把一个普通习惯——吃饭、通勤、购物或工作——变成提醒自己活在主临在中的祷告节奏。'),
  ],
  18: [
    n('18:1–8', '黑夜里的寡妇不断求公义', '一座城里有个不敬畏神、也不尊重人的官。一个寡妇不断来找他，说求你给我伸冤。官起初拒绝，最后为了不被她烦扰而为她办事。耶稣用这个不义的对比，问门徒：神的选民昼夜呼吁，祂岂不终久为他们伸冤吗？', '耶稣用坚持的寡妇鼓励门徒常常祷告、不可灰心，并把盼望放在公义的神而非不义的官。', '祷告不是因为神像冷酷的官，需要被骚扰才行动；比喻是从小到大作对比。寡妇没有权势，仍以持续发声寻求公义；门徒的等待不是被动忍受，而是相信神会审判、同时不放弃祈求。', '寡妇在古代法律和经济结构中常处于脆弱位置，律法多次要求保护她们；不义官的形象揭出制度中没有敬畏神、也不怕舆论的权力。经文没有说明她的案件内容，重点是她不沉默。', '可对照申 10:17–18、诗 10:17–18、诗 146:7–9；罗 12:12、启 6:9–11、雅 5:7–11 继续谈祷告、忍耐与公义。', '讨论：当公义迟延，我们如何避免变成冷漠或报复？操练：为一个公共公义议题持续代祷，同时采取合法、和平、尊重事实的行动支持受影响者。'),
    n('18:9–14', '站在远处的税吏', '两个人上圣殿祷告。法利赛人站着，自言自语地列出自己的禁食、奉献和“不像别人”；税吏却站在远处，不敢举目，只捶胸说：“神啊，开恩可怜我这个罪人。”耶稣说，回家算为义的是后者。', '耶稣宣告自我降卑、承认需要怜悯的人被神接纳，而不是靠比较建立义。', '法利赛人的行为不一定都是坏的，问题是他用善行把自己与别人隔开，并把神变成颁奖者。税吏没有提供辩护材料，只把自己放在恩典前；称义是神的礼物，不是羞辱别人后的自我感觉。', '禁食、十分之一和圣殿祷告都属于当时敬虔生活；税吏与罗马税务体系相连，承受群体的不信任。耶稣并没有说所有税吏都诚实，而是让一个被鄙视的人成为谦卑的榜样。', '可对照诗 51:16–17、弥 6:6–8、赛 57:15；罗 3:21–28、腓 3:4–9、彼前 5:5–6 展开称义与谦卑。', '讨论：我的祷告中有多少是在报告自己比别人好？操练：本周祷告先用三句话承认自己的需要、感谢神的怜悯，再为一个你容易比较的人祝福。'),
    n('18:15–17', '让小孩子到我这里来', '有人抱着婴孩来见耶稣，门徒却责备他们。耶稣叫孩子到祂那里来，说不要禁止，因为神的国正属于这样的人；不接受神国像小孩子的人，不能进去。', '耶稣接纳被门徒挡在外面的孩子，并以孩子的领受姿态说明进入神国的方式。', '孩子不是因为天真无罪才成为榜样，而是因为他们没有凭成就、地位或功劳谈判，只能领受。耶稣也把孩子从“打扰大人事工”的位置带到神国中心，教会必须为他们负责，而不是利用他们。', '古代儿童在法律、经济和公共话语上依赖成人，和现代儿童观不能完全等同；耶稣的动作尤其具有接纳边缘者的意味。婴孩被抱来，也说明信仰群体包含不能独立表达的人。', '可对照诗 127:3–5、撒上 1:27–28；太 18:1–6、可 10:13–16、彼前 2:2 都把孩子、谦卑和领受放在一起。', '讨论：我们是否只欢迎能贡献、能表达、能带来增长的人？操练：问一个孩子他对神、教会或世界的真实问题，不急着给标准答案，并改善一项保护儿童的实际安排。'),
    n('18:18–30', '富足的官舍不得放下所有', '一个官问耶稣当做什么才可以承受永生。他自幼遵守诫命，耶稣看着他，指出还缺少一件：变卖所有的分给穷人，然后来跟从。官忧忧愁愁地走了，因为他很富足。', '耶稣揭露财富成为这位敬虔官的最终安全感，并说明在人不能，在神凡事都能。', '耶稣不是给每个人一条机械的变卖清单；但对这位官，祂提出的命令确实是变卖、分给穷人并跟从。我们不能把个别命令轻易普遍化，也不能用“不是机械清单”把经文的锋利度磨平。门徒的奖赏不是交易，而是在人际、家庭和使命中领受神国的丰富。', '“官”可能指地方公共职务，路加没有说明他的具体职位；财富在古代常被看作神赐福的象征，所以门徒听见富足者难进神国特别震惊。耶稣引用诫命，随后将爱邻舍落实到财物；今天的回应应经过家庭、教会和实际责任的智慧辨别，而不是冲动清空财产。', '可对照出 20:1–17、利 19:18、申 15:7–11；太 19:16–30、腓 3:7–11、提前 6:17–19 平衡奉献、跟随与财富责任。', '讨论：什么是我会忧忧愁愁放不下的“最后一件”？操练：不要冲动清空财产，而是诚实盘点一项最控制你的资源，制定一个经过家庭和教会智慧确认的分享与简化计划。'),
    n('18:31–43', '耶稣往耶路撒冷去，瞎子在路旁呼喊', '耶稣把十二门徒拉到一边，第三次预告自己将在耶路撒冷受难、被杀、第三日复活；门徒仍不明白。随后，一个坐在路旁讨饭的瞎子听见人群经过，便喊“耶稣，大卫的子孙，可怜我！”众人叫他安静，他反而喊得更响。', '耶稣医治瞎子，使他看见并跟随；门徒虽有眼睛却暂时看不懂十字架，瞎子却看见耶稣是谁。', '路加把身体看见与属灵看见并置。瞎子没有被人群的制止压住，他清楚知道自己需要怜悯；耶稣让他自己说出想要什么，并把医治归于信心，恢复他作为主动跟随者的声音。这里不是把视力障碍归因于信心不足，而是记载一个具体的人转向耶稣、领受怜悯并被恢复。', '“大卫的子孙”是弥赛亚称呼，瞎子在路旁却比许多有地位的人更能辨认。古代视力障碍常使人失去谋生机会，讨饭是现实处境；耶稣没有只给施舍，而是恢复看见与跟随。', '可对照赛 35:5–6、撒下 7:12–16、诗 146:8；路 4:18、7:22、约 9 章把看见和弥赛亚使命贯穿起来。', '讨论：谁的声音在我们的群体中最容易被“安静”掉？操练：在一次公共讨论中，先邀请被忽略者表达需要，不替他发言，也不让多数人的方便盖过他的声音。'),
  ],
  19: [
    n('19:1–10', '王先进入人的家：救恩今天带来回转', '耶稣经过耶利哥，正准备继续前往耶路撒冷。人群围在路旁，一个名叫撒该的人却看不见祂。撒该是税吏长，又很富有；他跑到前面，爬上一棵桑树，只为看清楚耶稣。耶稣走到树下，抬头叫他的名字，请他赶快下来，并说今天要住在他家。撒该欢喜接待，旁边的人却开始议论。', '这一段首先告诉我们：耶稣主动寻找人，救恩也会进入人的真实生活。撒该的财富、名声、家庭和过去都没有被留在门外。第 10 节“人子来，为要寻找、拯救失丧的人”解释了整段发生的原因。', '叙事顺序很清楚。撒该只是想看看耶稣，耶稣却先停下来、叫出他的名字，并主动进入他的家。撒该还没有先证明自己已经悔改，耶稣已经向他伸出接纳的手；但这份接纳并没有把撒该的过去说成无所谓。撒该随后谈到穷人和赔偿，说明恩典会把钱财、受损的人和群体关系一起带到光中。在这段叙事里，赔偿是悔改结出的果子，不是用来购买救恩的价格。', '耶利哥在通往耶路撒冷的道路上，也是贸易和征税活动较集中的地方。“税吏长”是新约中很少见的称呼，至少说明撒该不是普通税吏；但我们不能从一个职位名称推断他过去每一笔钱的具体来源。第 8 节的“四倍”也不是所有亏欠的统一标准：出 22:1 针对特定盗窃规定四倍或五倍，利 6:5 和民 5:7 则提到归还并加五分之一。', '可对照出 22:1–4、利 6:1–5、民 5:7、结 33:14–16；路 3:12–14 把悔改落实在金钱和权力的使用上，路 5:27–32 与 15:1–32 则把耶稣的同席和寻找失丧者的使命连在一起。回看路 18:18–27，也能看见撒该与那位忧愁离开的富足官形成鲜明对照。', '讨论：我们的教会会不会像人群一样，自己靠近耶稣，却挡住别人看见祂？操练：如果你曾给别人造成明确的金钱、名誉或关系伤害，先向成熟牧者或专业人士求助，拟定具体的归还、澄清或赔偿方案。不要用“我已经悔改”要求受伤者立刻信任你、恢复关系或取消安全边界。', {
      verseInsights: [
        { range: '1–2', direct: '耶稣进入耶利哥，继续向前走。路加先写撒该的名字，再告诉我们两件事：他是税吏长，而且很富有。', depth: '这两项信息让读者知道，撒该不只是一个“可怜的小人物”。他有钱、有地位，也承受着群众对税吏的厌恶。路加把他放在上一章富足官的故事之后，继续追问：富足的人能不能进入神的国？关键不在财富本身，而在于他是否愿意让耶稣把自己从财富和污名的捆绑中带出来。' },
        { range: '3–4', direct: '撒该想看清楚耶稣是谁，但因为身材矮小，又被人群挡住，于是跑到前面，爬上一棵桑树。', depth: '他确实在寻找耶稣，但故事的转折不在于他爬得多高，而在于耶稣停下来，抬头看他。人群本来应该帮助人接近耶稣，却在这一刻成了阻碍。教会也可能如此：我们已经站在主身边，却无意中挡住了别人。' },
        { range: '5–7', direct: '耶稣叫撒该赶快下来，说今天必须住在他家。撒该欢喜接待，众人却抱怨耶稣竟然到罪人家里作客。', depth: '“必须”不是耶稣临时起意，而是表明这次相遇在神的救赎计划中有必要。“今天”也说明救恩不是遥远的理论，而是在此刻临到一个具体的人。耶稣先主动接近撒该，随后才有撒该的回应；但主的接纳不是纵容，而是把他带进可以真实改变的关系。' },
        { range: '8', direct: '撒该站起来说，他要把一半财物给穷人；如果曾讹诈过谁，就还四倍。希腊文动词用现在时，所以既可以理解为当场作出的承诺，也可以理解为对自己一贯做法的公开说明。', depth: '这节存在语法和解释上的争议，但两种读法都把读者带到同一个问题：遇见耶稣之后，钱财和受损者怎么办？若是承诺，这是悔改的具体行动；若是申辩，则提醒我们不要只凭群众的指控定一个人的罪。无论如何，属灵经历不能把经济责任排除在外。' },
        { range: '9–10', direct: '耶稣宣告救恩今天到了撒该家，因为他也是亚伯拉罕的子孙；然后说明人子来，是要寻找并拯救失丧的人。', depth: '“亚伯拉罕的子孙”不是说撒该此刻才成为犹太人，而是耶稣公开确认：这个被群体排斥的人仍属于神应许的范围。“到了这家”说明救恩进入家庭和关系网络，但不等于家里每个人都自动完成了信仰回应。救恩的主动者是来到撒该家的耶稣，不是撒该的捐款。' },
      ],
      interpretationNotes: [
        { title: '第 8 节应当怎样讲？', text: '正文可以先按叙事最自然的方向理解为撒该正在作出悔改承诺，同时在学术说明中交代另一种现在时读法。这样既不把争议藏起来，也不会让初读者以为整段的重点只是语法问题。无论采取哪种读法，耶稣都把撒该的财富生活带到公开的光中。' },
        { title: '恩典和赔偿是什么关系？', text: '耶稣先看见撒该、叫他的名字、进入他的家；赔偿随后出现。因此赔偿不是换取接纳的门票，而是恩典在现实生活中的果子。赔偿也不等于受伤者必须恢复信任或关系；真正的修复要尊重事实、法律、安全和受伤者的选择。' },
      ],
    }),
    n('19:11–27', '神的国不会按人的时间表立刻完成：等候中的忠心', '撒该刚刚听见“今天救恩到了这家”，耶稣也越来越接近耶路撒冷。跟随祂的人很容易以为，神的国马上就会公开、决定性地实现。耶稣于是讲了十锭银子的比喻：一位贵胄要到远方取得王位，临行前把银子交给仆人，吩咐他们经营；他回来以后，逐一召集仆人交账。故事最后同时出现奖赏、责备和审判。', '这里并不是圣经里一个叫“立即国度”的术语。它描述的是一种错误期待：人以为耶稣既然已经接近耶路撒冷，神的国就会马上以公开、决定性的方式出现——耶稣立刻在圣城显明王权，众人也立刻看见局势改变。耶稣纠正的是人对国度显现的时间和方式的想象，不是否认神的国已经在祂身上开始临到。王回来以前，门徒不是等待一场即时的政治胜利，而是忠心使用已经领受的托付。', '这段不是一堂教人靠投资赚钱的课程。前两位仆人都说“你的银子赚了”，他们没有把成果当成自己的功劳；主人给他们的奖赏也不是私人享受，而是更大的治理责任。第三位仆人失败，不只是因为收益少，而是因为他对主人的恐惧和错误想象使他完全不行动。比喻中的贵胄很严厉，结尾也出现带有暴力色彩的审判场面；这个难点必须认真面对，却不能拿来为现实中的剥削、威吓和暴力领袖背书。', '一锭银子约等于一百个银钱，是一笔有实际分量、却不是天文数字的托付。具体购买力会因时代和地区而不同，不宜把它换算成一个过度确定的现代工资数字。贵胄远行取得王位，可能让第一世纪听众想起希律家族向罗马寻求统治确认的历史，但这只是背景回声，不表示比喻中的贵胄就是某一位历史人物，也不表示每个细节都直接对应耶稣。', '可对照但 7:13–14 的受国图像、路 8:18 和 12:35–48 关于听道与交账的教导；太 25:14–30 是相似但不完全相同的比喻。徒 1:6–11 又一次纠正门徒对“现在就复兴国度”的期待，把他们转向圣灵中的见证。', '讨论：我是否因为主的工作暂时不明显，就把等待当成可以不负责任的理由？操练：选择一项已经交在你手中的时间、能力、金钱或关系责任，用两周完成一个实际祝福别人的行动。复盘时先问自己是否诚实、忠心、使人得益，不要只看数字大小。', {
      verseInsights: [
        { range: '11', direct: '耶稣靠近耶路撒冷，听众因此以为神的国马上就要公开实现。路加先说明讲比喻的原因，再让故事展开。', depth: '重点不是“神的国从来没有来到”，而是听众以为它会在耶路撒冷立刻以公开、决定性的方式出现。跳过这一节，比喻就容易被读成一般的理财故事；抓住这一节，问题就变成：当神没有按我的时间表行动时，我是否仍然忠心？' },
        { range: '12–14', direct: '一个贵胄到远方去取得王位。他离开以前，把十锭银子分给十个仆人，要求他们经营；他的百姓却派代表说不愿意他作王。', depth: '听众熟悉的王权和政治冲突，为故事增添了现实压力。耶稣借着他们熟悉的世界讲话，但没有要求我们把贵胄的每个性格直接套在祂身上。故事至少清楚分出两类回应：有人接受托付并行动，有人拒绝王权。' },
        { range: '15', direct: '贵胄得了王位回来，先召仆人来，查问他们用那一锭银子赚了多少。', depth: '等待在这里不是空白时间，而是受托时间。王的归来表示人的行动会被认真看待。恩典不是取消责任；神先把可以使用的托付交给人，然后要求人诚实交账。' },
        { range: '16–19', direct: '第一位赚了十锭，第二位赚了五锭；两个人都把成果归给主人的那一锭。主人按他们的忠心，分别让他们管理十座城和五座城。', depth: '他们的成果不同，却都得到肯定。奖赏的形式是更大的治理责任，不是更奢华的私人生活。这里的重点不是谁最有能力，而是谁在小事上忠心。人的处境和成果可以不同，忠心却不会被神忽略。' },
        { range: '20–23', direct: '第三位仆人把银子包在手巾里。他说自己害怕主人，因为主人严厉，收取自己没有存入的，收割自己没有撒种的。主人就用他自己的话反问他：如果你真这样认识我，为什么连最基本的事也没有做？', depth: '仆人的言语和行为彼此矛盾。他声称害怕主人，却没有采取任何最小的行动来处理托付。经文揭露恐惧如何变成不行动的借口；这不是授权任何领袖用“我很严厉”来要求别人承担不义的压力。' },
        { range: '24–26', direct: '主人把第三个仆人的一锭拿走，交给已经有十锭的人，并说有的还要加给他，没有的连他所有的也要失去。旁边的人却提出疑问：“他已经有十锭了。”', depth: '在这个比喻里，这句话指向“托付是否被使用”。愿意承担责任的人，能力和责任会一起增长；拒绝使用托付的人，最后连原有的位置也会失去。不能把它抽成“富人理应越来越富”的经济规律，因为路加在别处反复警告财富和权力的危险。' },
        { range: '27', direct: '故事最后，拒绝贵胄作王的仇敌被带来，在王面前受死。这是比喻中最令人不安的审判场景。', depth: '耶稣没有把拒绝神的王权说成没有后果，但审判的执行权属于王，不属于门徒。接下来耶稣不是带军队进城，而是骑着驹走近耶路撒冷，并为这座城哭泣。这个次序帮助教会谨慎地谈论王权、审判和暴力。' },
      ],
      interpretationNotes: [
        { title: '贵胄是不是在每一处都代表耶稣？', text: '离开、得国、回来和交账，都可以与耶稣的王权联系起来，这是上下文支持的方向；但比喻中的贵胄之所以严厉，也带有当时听众熟悉的政治世界的影子。较稳妥的读法是承认比喻有王权类比，却不把贵胄的每个特征都当作耶稣的品格定义。' },
        { title: '这段只是讲主再来延迟吗？', text: '它确实纠正“神的国一到耶路撒冷就马上公开完成”的期待，也保留王回来交账的盼望；但重点不是让我们制作一张末世时间表，而是说明国度不会按群众预想的即时政治方式完成。等待期间，门徒仍然有清楚、可问责的使命。' },
        { title: '怎样面对故事中的暴力？', text: '不能把第三位仆人的不行动浪漫化，也不能把主人形象拿来合理化现实中的剥削。带领小组时可以承认这个难点：比喻使用了王权审判的语言，最终审判属于神；教会在现实中却必须拒绝以暴力和属灵威吓控制人。' },
      ],
    }),
    n('19:28–35', '走近圣城（一）：王以和平的方式前行', '比喻讲完，耶稣继续走在前面，向耶路撒冷上行。祂到了伯法其和伯大尼附近的橄榄山，差两个门徒到前面的村子去，吩咐他们牵来一匹从未有人骑过的驹。有人询问时，门徒只回答：“主要用它。”耶稣没有等局势把祂推向圣城，而是主动安排了这场公开行动。', '撒该家中的“今天”救恩，接着进入关于耶稣王权的叙事。耶稣清楚知道自己正走向耶路撒冷，也用骑驹的行动公开表明自己是王；但祂选择的是谦和、和平的王，而不是靠战马和武力征服的王。', '路加从 9:51 起不断提醒读者，耶稣已经定意向耶路撒冷去。第 28 节说祂“走在前面”，让我们看见这条路不是意外把祂拖过去的。祂知道前面有受苦和死亡，仍然主动前行。无人骑过的驹可能表示它被特别保留下来，但经文的重点不是建立关于坐骑的独立教义，而是让读者看见耶稣主动、清楚地表明祂怎样作王。', '伯法其和伯大尼在耶路撒冷东面的橄榄山一带。从耶利哥到耶路撒冷是明显的上行路程。路加写“驹”，与亚 9:9 中谦和的君王相呼应；但路加没有在这里直接引用亚 9:9，所以可以说这是旧约意象的回声，不必声称每个细节都在逐项应验。', '可对照亚 9:9–10，看见谦和的王与和平的国度；撒下 7:12–16 提供大卫王位应许的背景。再连到路 9:51、13:33、18:31–34，观察耶稣怎样主动走向耶路撒冷、受死与复活。', '讨论：我心里所期待的领袖，是否一定要强势、拥有资源，并且压过所有反对者？操练：在一项你有决定权的事情上，用说明、聆听和承担代价来领导，不用威吓或地位逼人顺服。', {
      verseInsights: [
        { range: '28', direct: '耶稣讲完比喻，便走在前面，继续上耶路撒冷去。', depth: '“走在前面”是一个很有画面的动作。耶稣不是被局势推着走，而是主动走向自己已经预告的受难。祂的王权首先表现为顺服父、承担使命，而不是占据权力中心。' },
        { range: '29', direct: '耶稣到了伯法其、伯大尼和橄榄山附近，便差遣两个门徒。', depth: '从 9:51 开始的漫长旅程到了最后阶段。橄榄山既是具体地理位置，也承载着先知和末世盼望，所以这段路同时具有现实和象征的重量。' },
        { range: '30–34', direct: '门徒找到一匹拴着、从未有人骑过的驹。若有人询问，就回答“主要用它”。事情一一照耶稣所说的发生。', depth: '这里最清楚的重点是耶稣掌握行动，并且知道怎样开始这场王权宣告。经文没有说明祂是否事先与主人约定，也没有要求我们在这个问题上作过度推测；它要我们看见的是门徒顺服，耶稣的计划向前推进。' },
        { range: '35', direct: '门徒把驹牵来，把衣服搭在上面，扶耶稣骑上。', depth: '这是一个公开的王权动作。耶稣接受王者的尊荣，却选择与谦和、和平相连的坐骑。祂没有否认自己是王，但拒绝用军队、战马和报复来定义王权。' },
      ],
      interpretationNotes: [
        { title: '精读路加时，不要自动补入其他福音书的细节', text: '路加没有写棕树枝，也没有写“和散那”。四卷福音可以互相参照，但本段应先尊重路加特别留下的词语：驹、衣服、门徒、王、和平和荣耀。' },
        { title: '驹的意义应当说到哪里？', text: '它可以唤起亚 9:9 中谦和君王的盼望，也使耶稣的王权与军事征服拉开距离。但路加没有在此直接解释每个象征，因此应把它作为有根据的旧约回声，而不是延伸成经文没有说的细节。' },
      ],
    }),
    n('19:36–40', '走近圣城（二）：王受到欢呼，却不是人想象的王', '耶稣骑着驹从橄榄山向前走，门徒把衣服铺在路上。因为亲眼看见祂所行的一切神迹，众门徒大声赞美神，并用诗篇的语言宣告这位王是奉主名来的。几个法利赛人要求耶稣制止门徒，耶稣却回答：如果他们闭口，石头也会呼叫。欢呼是真实的，但这位王即将面对的拒绝也已经近在眼前。', '门徒正确地承认耶稣是王，但他们还需要让十字架来解释这位王究竟怎样作王。路加把“天上有和平、至高之处有荣耀”的赞美，和降生时天使的颂歌连接起来。耶稣带来的和平有天上的根基，却不会立刻变成群众期待的政治胜利。', '门徒的赞美不是错误，耶稣也没有责备他们；但这段不能脱离后面的哭城、圣殿行动和十字架来读。经文没有说这里的欢呼者后来就是喊“钉祂十字架”的同一批人，也没有说明法利赛人的唯一动机。我们可以谈人心会摇摆，却不能把没有写出的前后联系当成经文事实，更不能借此集体定罪犹太人。', '把衣服铺在路上，是向王者表达尊荣的动作。诗 118 本来就带有朝圣和求拯救的背景，路加特别保留了“王”这个称呼；他没有写棕树枝或“和散那”。“在天上有和平、在至高之处有荣耀”回响路 2:14 的天使颂歌，说明路加把耶稣的降生、走近圣城和复活后的荣耀放在同一条救赎线上。', '可对照诗 118:25–27、王下 9:13 和亚 9:9–10；路 2:13–14 与本节互相照亮。石头呼叫可以放在先知式的见证图像中理解；腓 2:5–11 则进一步说明这位王的升高经过降卑和十字架。', '讨论：我们的敬拜是在欢迎耶稣按祂的方式作王，还是借热烈气氛确认自己的期待？操练：把一次赞美转成一项和平行动，例如停止传播未经证实的指控、主动修复误会，或在冲突中先诚实聆听对方。', {
      verseInsights: [
        { range: '36', direct: '耶稣前行时，人把衣服铺在路上。路加没有写树枝，画面集中在衣服、道路和行进中的王。', depth: '人不只是口头欢迎，也把自己的衣服放在王所走的路上。这是公开尊荣的动作，同时也提出一个问题：我们愿意把什么放在耶稣的道路上？不过，真正的回应还必须经过十字架对王权的重新解释。' },
        { range: '37', direct: '耶稣走到橄榄山下坡处，众门徒因所看见的一切神迹，欢喜大声赞美神。', depth: '路加明确说是“众门徒”，并把赞美的理由放在耶稣已经做过的事上。他们的经验是真实的，赞美也是真实的；但他们对受苦道路的理解还没有完全成熟。门徒需要的不只是更大的热情，也需要让耶稣继续教导他们。' },
        { range: '38', direct: '门徒宣告：“奉主名来的王是应当称颂的”，又说：“在天上有和平，在至高之处有荣耀。”', depth: '他们用诗 118 的语言承认耶稣是王。路加又让人听见路 2:14 的回声：耶稣从降生到走近圣城，一直处在神的和平与荣耀之中。但这和平不会靠群众的欢呼立刻完成，所以欢呼之后紧跟着就是耶稣的眼泪。' },
        { range: '39', direct: '人群中有几个法利赛人要求耶稣责备门徒。', depth: '路加没有说明他们究竟是担心政治后果、反对神学宣告，还是两者都有。好的解释不必替他们编造内心独白，只要看见：他们要求停止的，正是门徒对王的公开承认。' },
        { range: '40', direct: '耶稣说，如果门徒闭口，石头也会呼叫。这是带有夸张色彩和先知性意味的宣告。', depth: '神在耶稣身上所做的事，不能靠人的禁声取消。石头不是教会用更大音量压过别人的许可证，而是说明神的作为最终不受人控制。' },
      ],
      interpretationNotes: [
        { title: '这是不是已经完全实现的凯旋？', text: '门徒确实在欢迎王，耶稣也接受这一宣告；但路加把赞美、哭城、圣殿和十字架放在同一条路上。若只把它读成胜利巡游，就会错过这位王以眼泪、真理和受苦带来和平的方式。' },
        { title: '不要把不同群体混成一群人', text: '这里是“众门徒”，后来则出现宗教领袖、彼拉多和不同的群众。可以讨论人心的摇摆，却不要把所有人物都简化成一个“犹太群众”，更不能用这段经文为反犹主义提供依据。' },
      ],
    }),
    n('19:41–44', '走近圣城（三）：王为看不见和平的城哭泣', '耶稣越来越靠近耶路撒冷，看见那座城就哭了。刚刚接受门徒欢呼的王，此刻没有沉浸在掌声里；祂为这座城没有认出什么能带来和平而悲伤。接着，祂用筑垒、包围、四面困住和拆毁的画面，预告战争将怎样临到城和城中的居民。', '耶稣的王权不是报复性的王权。祂一面说出拒绝神眷顾的严重后果，一面为将要受毁的城流泪。爱使祂哭泣，真理使祂发出警告；这两者在耶稣身上同时存在。', '这里的“和平”不只是没有战争，也包括接受神在耶稣里带来的和好、公义，并接受祂所带来的王权。耶路撒冷没有认出这条路，后果便进入具体历史：围城、饥荒、死亡和家庭破碎。耶稣的眼泪不允许教会对灾难幸灾乐祸；祂的警告也提醒我们，爱不是永远不说后果。', '围城和城被拆毁的语言，很容易让人想到公元 70 年罗马毁坏耶路撒冷的历史记忆。这能帮助我们感受预告的现实重量，但不能单靠这几节确定路加全书的写作日期，也不能把战争死者简单说成“活该”。“眷顾”在圣经中可以指神临到、察看并施行拯救或审判；路加把神的眷顾集中呈现在耶稣来到这座城的时刻。', '可对照路 1:68、1:78 和 7:16，观察“眷顾”如何先指向神带来救赎；路 13:34–35 已经写过耶稣为耶路撒冷哀哭，路 21:20–24 则更具体地谈到耶路撒冷被围困。最后读路 24:46–49，会看见复活的耶稣仍从耶路撒冷开始传悔改和赦罪的信息。', '讨论：面对城市、国家或教会的罪，我们更容易冷漠、愤怒，还是能像耶稣一样既说真话又流泪？操练：为所在城市的一项真实伤痛查证资料、哀恸祷告，并选择一个合法、和平、实际的参与行动。不要把每一场灾难简单解释成神对某群人的直接报应。', {
      verseInsights: [
        { range: '41', direct: '耶稣临近耶路撒冷，看见这城就哭泣。路加把祂的哭泣放在王者欢呼之后。', depth: '耶稣不是站在远处宣判一座抽象的城市，而是看见真实的人和将要发生的毁坏。祂的审判不是冷漠的报复；祂的眼泪也不是对罪和后果的否认。' },
        { range: '42', direct: '耶稣说，这城如果在这一天知道什么能带来和平就好了；但如今，它看不见这条道路。', depth: '和平已经随着谦和的王来到，但耶路撒冷没有认出祂。这里既保留神主权的奥秘，也保留人的责任。我们不能用“看不见”来替自己不回应真理开脱。' },
        { range: '43–44上', direct: '敌人将筑垒、包围、四面困住这座城，摧毁城和城中的居民，不留一块石头在另一块石头上。', depth: '这是围城战争的具体图像，不是抽象的“灵性失败”。拒绝和平道路会进入公共历史并带来真实伤害，但本段不是教人把每场战争都简单归咎于受害者的个人罪。耶稣自己也将在罗马暴力下受死。' },
        { range: '44下', direct: '耶稣说，这座城之所以走向悲剧，是因为没有认出神来眷顾它的时刻。', depth: '神的眷顾已经借着耶稣的教导、医治、与人同行，以及祂走向圣城的行动临到。人可能熟悉宗教场所、经文和节期，却仍然错过神实际临到的方式。辨认神，不是追逐神秘时刻，而是看见耶稣怎样带来和平、怜悯、悔改和公义。' },
      ],
      interpretationNotes: [
        { title: '这段不能成为反犹主义的依据', text: '耶稣、门徒、耶路撒冷居民和路加所承接的以色列故事都在犹太世界内部。这是先知为自己的百姓哭泣，不是外族对“犹太人”的蔑视。路加—使徒行传仍然把耶路撒冷写成复活见证和万民使命的起点。' },
        { title: '公元 70 年的历史背景应当怎样使用？', text: '围城语言与罗马毁城高度相应，帮助我们感受这不是抽象威吓；但这不证明罗马在道德上正确，也不允许我们把战乱死者当成“活该”。历史背景应当帮助我们理解耶稣的眼泪、警告和和平之路，而不是变成定年或报应论的唯一工具。' },
      ],
    }),
    n('19:45–48', '走近圣城（四）：王进入圣殿，恢复祷告与教导', '耶稣进入圣殿，把正在那里做买卖的人赶出去。祂用先知的话解释自己的行动：神的殿应当是祷告的殿，却被人弄成了贼窝。从那以后，耶稣天天在殿里教导；祭司长、文士和百姓中的领袖想杀祂，却一时找不到机会，因为百姓都在专心听祂。', '这位王进入的不是宫殿，而是圣殿。祂先揭露不义如何占据敬拜空间，再用持续教导把这个空间重新指向祷告和真理。圣殿行动既是审判，也是恢复；它也为下一章关于“你凭什么权柄做这些事”的争论作了铺垫。', '路加没有说所有商业活动本身都是罪，也没有在本段交代具体价格是否欺诈。耶稣引用耶 7 的“贼窝”，重点是作恶的人把圣殿当成躲避审判的安全洞穴：外面继续不义，里面却以宗教仪式获得保护。祂不是反对圣殿本身，而是反对圣殿被用来遮盖不义；祂赶出买卖者以后，立刻留下来天天教导。', '圣殿既是祷告、献祭和朝圣的中心，朝圣者也确实需要在那里取得祭物或处理相关事务；因此不能只凭“有买卖”就推断每个参与者都在犯罪。第 46 节把赛 56:7 和耶 7:11 放在一起：前者强调万民祷告，后者批判虚假的圣殿安全。路加没有写其他福音书中的每个动作，所以解读应以路加保留下来的行动和引文为主。', '可对照赛 56:6–7 和耶 7:1–11，看见祷告之殿与虚假安全的张力；玛 3:1–4 描写主临到圣殿并施行炼净。路 20:1 接续耶稣在殿里教导，徒 7:48–50 和林前 3:16–17 则继续追问神同在、圣洁和祷告群体的意义。', '讨论：我们的聚会、奉献、事工品牌和领袖制度，是帮助人亲近神，还是给不透明和不义提供属灵外衣？操练：审查一项教会财务或服事流程，明确用途、审批、申诉和弱者保护。不要把本段简化成“教会不可有任何收费或买卖”，而要追问资源是否真的服务祷告、公义和人的进入。', {
      verseInsights: [
        { range: '45', direct: '耶稣进入圣殿，开始赶出在那里做买卖的人。路加只写了行动和对象，没有补充鞭子、桌子、兑换银钱或具体欺诈的细节。', depth: '这是一个带有先知性的审判行动：耶稣刚为不认识神眷顾的城哭泣，随即进入这座城的宗教中心。问题已经不只是个人道德，而是敬拜空间是否被不义占据。忠于路加的写法，就是既不淡化行动，也不把其他记载或想象当成这里明说的事实。' },
        { range: '46', direct: '耶稣用经上的话说明，神的殿应当是祷告的殿，他们却把它变成了贼窝。这句话结合了赛 56:7 和耶 7:11。', depth: '“贼窝”不只是偷窃发生的地方，也指作恶者事后躲藏、以为自己安全的洞穴。耶稣揭露的是宗教被用来遮盖不义。祷告和公义一旦分开，建筑再神圣，也会失去它的使命。' },
        { range: '47', direct: '耶稣每天在圣殿里教导；祭司长、文士和百姓中的领袖则设法杀祂。', depth: '恢复不只是赶走错误，也包括用持续的教导把这个空间重新交还给祷告和真理。冲突集中在具体的领袖群体，不是“所有犹太人”一致拒绝耶稣。领袖想保护自己的权位，耶稣却把真理公开放在百姓面前。' },
        { range: '48', direct: '领袖暂时找不到下手的办法，因为百姓都专心听耶稣的话。路加用“听”结束本章。', depth: '百姓的聆听暂时使领袖不敢下手，但群众一时的支持并不能成为最终保障。耶稣仍然会走向受死；门徒必须从一时被吸引，走向持续听道和遵行。' },
      ],
      interpretationNotes: [
        { title: '耶稣反对一切买卖吗？', text: '献祭和朝圣客观上需要相应的供应，路加也没有逐项说明交易的罪状。先知引文把焦点放在圣殿使命被扭曲：祷告之地成为不义者的安全洞穴。因此今天不能只禁止某种形式，却保留不透明财务、排斥弱者和权力滥用。' },
        { title: '这是洁净，还是圣殿审判？', text: '两方面都在场。耶稣赶出买卖者，并以祷告和教导重新定义这个空间；但行动紧接着哭城，也引发领袖谋杀，带有审判旧秩序的意味。把它称为“洁净”时，不要忘记它同时在问：这个敬拜空间是否还忠于神的使命？' },
      ],
    }),
  ],
  20: [
    n('20:1–8', '你凭什么权柄做这些事？', '耶稣在圣殿教导、传福音，祭司长、文士和长老一起来质问祂：“你仗着什么权柄？”耶稣反问约翰的洗礼来自天上还是人间。他们不愿回答，因为无论回答哪一边，都要面对自己的不诚实。', '耶稣不被宗教领袖的审问牵着走，揭露他们不是缺少信息，而是不愿承担真理带来的后果。', '权柄问题不能只问“谁批准你”，还要问提问者是否愿意顺服已经知道的真理。耶稣不是逃避回答，而是让领袖先面对他们如何拒绝约翰；不诚实的中立也可能是抵挡。', '圣殿是教导和权力争议的公共场所，祭司长、文士和长老代表不同层面的宗教与社会权威。约翰的洗礼已成为公众事件，承认其来自神就意味着承认自己需要悔改。', '可对照出 3:1–12、撒上 15:22–23、耶 7:23–28；约 5:30–47、徒 4:7–12 继续谈基督权柄与人拒绝见证。', '讨论：我问“谁给你权柄”时，是真的想寻求真理，还是想保护自己的位置？操练：在一次意见冲突中，先说出自己已经知道且需要顺服的部分，再提出对他人的问题。'),
    n('20:9–19', '园户拒绝主人，甚至杀了爱子', '耶稣讲一个葡萄园的故事：主人把园子租给园户，收获时一次次差仆人去收果子，园户却打伤、赶走他们；最后主人差遣爱子，他们竟把他杀在园外。听众立刻明白这比喻指向谁。', '园户代表拒绝神差来的先知与爱子；被弃的石头将成为房角的头块石头。', '神的忍耐不是认可园户的暴力；一次次差派显出神长期呼唤回转。爱子被杀看似失败，却成为神建立新群体的根基。耶稣也让宗教领袖听见：拥有葡萄园的管理权，不等于拥有主人的位置。', '葡萄园是以色列常见的农业与先知图像，租佃关系涉及地主、园户和收成。耶稣引用诗 118 的房角石，说明被拒绝者将由神设为关键；“园外”也预示耶稣在城外受死。', '可对照赛 5:1–7、诗 118:22–23、王上 21:1–16；约 1:11、徒 4:10–12、彼前 2:4–8 继续说明爱子、房角石和新群体。', '讨论：神托付给我的“葡萄园”是什么，我是否把管理权当成所有权？操练：把一项团队、家庭或教会资源的决策过程变得更透明，让真正的主人——神和受托群体——被尊重。'),
    n('20:20–26', '把该撒的归该撒，神的归神', '有人假装为善，派探子来问纳税给该撒可以不可以。他们想把耶稣逼入政治陷阱：说可以，群众可能不满；说不可以，便可控告祂。耶稣要一枚银币，问上面的像和号是谁，随后说该撒的归该撒，神的归神。', '耶稣拒绝被简化成政治口号，要求在公共责任与对神的终极忠诚之间作出分辨。', '这句话不是把信仰和公共生活彻底分开，也不是为任何政府无限授权。银币上有统治者的像，人的生命却带着神的形象；缴税可以是公共责任，敬拜和良心不能被国家夺取。', '罗马税是占领秩序下的现实负担，银币上的肖像和称号可能带来宗教敏感。耶稣没有给出一套现代政体理论，而是在陷阱中保持诚实、避免以暴力夺王位。', '可对照创 1:26–27、但 3:16–18、耶 29:4–7；罗 13:1–7、徒 5:29、彼前 2:13–17 帮助我们平衡公共责任与敬畏神。', '讨论：我的政治忠诚或反感，是否已经取代了对神的忠诚？操练：面对公共议题，先查证事实、尊重不同良心，再问“怎样既承担公民责任，又不把任何政权当作救主”。'),
    n('20:27–40', '神不是死人的神，乃是活人的神', '撒都该人不相信复活，拿七兄弟为例提出一个尖锐的婚姻问题：复活时她是哪一个人的妻子？耶稣指出他们既不明白圣经，也不明白神的能力；复活生命不简单复制今世婚姻制度，因为人不能再死，乃像天使一样，是神的儿女。', '耶稣以摩西荆棘篇证明神是亚伯拉罕、以撒、雅各的神；在神那里，列祖都活着。', '耶稣没有用来世细节满足好奇，而是把盼望根基放在神与人的关系和神的信实。复活不是今生关系的抹除，却也不是把今世全部制度原样延长；神的能力超越我们拿来设问的框架。', '撒都该人可能以摩西五经为最高权威，因此耶稣从出 3 章论证复活；七兄弟婚姻问题来自申 25:5–10 的弟兄继承婚传统。婚姻制度在复活中的状态，文本只给出方向，不支持过度绘制天堂社会结构。', '可对照出 3:6、申 25:5–10、伯 19:25–27；林前 15:12–28、帖前 4:13–18、启 21:1–5 继续展开复活盼望。', '讨论：我对复活的盼望，是具体信靠神，还是被一套想象画面绑架？操练：为一位哀伤者提供不虚假的复活盼望，同时允许他哭泣，不用未来应许压住现在的悲伤。'),
    n('20:41–47', '大卫称祂为主，文士却吞吃寡妇的家产', '耶稣先问：人怎么说基督是大卫的子孙？诗篇中大卫却称祂为主。随后祂警告门徒防备喜欢长衣、首位和长祷告的文士，因为他们侵吞寡妇的家产，假意作很长的祷告。', '耶稣既是大卫之子，又超越大卫；祂揭露宗教外表和剥削弱者之间的矛盾。', '弥赛亚不是只满足民族王权的延续，而是大卫也要向祂俯伏的主。教导者的危险不在衣服本身，而在用属灵尊荣建立特权、吞吃脆弱者；用很长的祷告遮盖伤害，只会使假冒更加严重。', '古代长衣、市场问安和首位都具有社会尊荣意义；寡妇常是最需要法律与经济保护的人。关于文士如何具体吞吃产业，经文未交代，重点是宗教权力与弱者受害的反差。', '可对照诗 110:1、撒下 7:12–16、申 24:17–22；弥 3:9–11、太 23:1–14、雅 3:1 都警告以教导谋取权力。', '讨论：我们如何评估属灵领袖，是看表达、服装和影响力，还是看他怎样对待弱者、金钱和权力？操练：建立小组财务和领导的透明机制，让被服事者有安全反馈的渠道。'),
  ],
  21: [
    n('21:1–4', '两个小钱，比众人投得更多', '圣殿奉献箱旁，耶稣看见富人把礼物投进去，也看见一个穷寡妇投下两个小钱。声音很轻，金额很小，耶稣却说她投的比众人更多，因为别人是拿有余的来投，她是从不足中把一切养生的都投上。', '神看重奉献背后的信靠与代价，不以金额大小简单衡量人的敬虔。', '这段首先是耶稣的观察，不是给教会领袖压迫穷人奉献的工具。寡妇的慷慨令人感动，但紧接着耶稣会批评吞吃寡妇家产的宗教系统；我们必须同时看见个人信靠和制度责任。', '奉献箱可能位于圣殿公共区域，钱币面额很小；寡妇在古代社会常缺乏稳定收入。路加没有说明她的两个钱如何被使用，也没有把贫穷本身说成属灵美德。', '可对照王上 17:8–16、申 15:7–11、弥 6:8；可 12:41–44、林后 8:1–15 既肯定甘心，也要求群体彼此均平。', '讨论：我们是否用“感动”赞美穷人的牺牲，却不问他们为什么被迫匮乏？操练：教会或小组在鼓励奉献时，同时建立对弱者的实际保障，公开说明资源如何使用。'),
    n('21:5–24', '圣殿会被拆毁，门徒要在混乱中作见证', '有人赞叹圣殿的石头和奉献装饰，耶稣却说将来没有一块石头留在石头上。门徒追问何时发生；耶稣谈战争、地震、饥荒、逼迫，也提醒不要被冒名的弥赛亚和惊慌牵走。', '耶稣预告圣殿与耶路撒冷将经历毁坏，劝门徒在动荡中忍耐、作见证，不把每一次灾难都当成末日密码。', '耶稣没有否认历史灾难的真实，也没有让门徒靠猜日期获得安全感。逼迫成为见证机会，忍耐不是消极挨打，而是在混乱中守住真理、保护群体、辨认虚假拯救者。', '耶路撒冷圣殿在犹太身份和敬拜中极其重要；公元一世纪战争最终导致圣殿在公元 70 年被毁，这可作为经文历史视野中的重要背景，但不能把所有末世语言简单压缩成单一日期。', '可对照但 7–9、耶 7:1–15、弥 3:9–12；路 19:41–44、徒 6–8、彼前 4:12–19 帮助我们在审判和见证之间阅读。', '讨论：危机消息大量涌来时，我怎样分辨事实、谣言和末日煽动？操练：建立一个可靠信息和彼此关怀的习惯，遇到灾难先核实、祷告、帮助，不转发未经证实的恐惧。'),
    n('21:25–28', '当人子来到，抬起头来', '海洋翻腾、列国困惑、天势震动的图像出现；人因恐惧而失去方向。就在这样的画面中，耶稣不是叫门徒低头逃避，而是说当这些事发生时，要挺身昂首，因为得赎的日子近了。', '末世显明会带来审判与恐惧，但对门徒而言也是救赎完成的盼望。', '基督徒的盼望不是否认世界会震动，而是知道震动不会拥有最后解释权。昂首不是骄傲和幸灾乐祸，而是从恐惧中重新站起来，带着救赎盼望作清醒、怜悯和诚实的人。', '“人子”承接但以理 7 章的云中人物，既有受苦者也有末世掌权者的意象。宇宙性语言常用来表达政治秩序和受造界被摇动，不能只当作现代灾害时间表。', '可对照但 7:13–14、赛 13:9–13、珥 2:30–32；帖前 4:13–18、启 1:7 与罗 8:18–25 连接受造界叹息和最终更新。', '讨论：我的末世盼望使我更勇敢爱人，还是更热衷判断别人？操练：为一个受危机影响的群体做一件具体善事，把“抬起头来”的盼望转成可见的陪伴。'),
    n('21:29–36', '无花果树发芽，警醒而不沉醉', '耶稣指着无花果树和众树：一发芽，人就知道夏天近了。祂把门徒从植物的季节转到自己的心：要谨慎，免得贪食、醉酒和今生的思虑使心被压住；要时刻祈求，得以站立在人子面前。', '门徒要从时代的迹象辨认神的工作，同时保守心不被放纵和忧虑麻痹。', '警醒不是每天追踪惊悚新闻，而是让心保持清醒、节制、祷告和盼望。今生思虑会与醉酒和贪食并列，说明过量享乐与过量焦虑都能使人失去灵性的敏锐。', '无花果树发芽是巴勒斯坦季节变化的日常观察；路加不要求门徒准确计算末日日期。古代“醉酒”也可象征被生活欲望压制，教会需要把末世教导落实为身体与消费节制。', '可对照箴 23:29–35、耶 8:7、但 12:3；太 24:32–44、罗 13:11–14、帖前 5:4–8 继续谈清醒生活。', '讨论：我现在被什么压住心，以致没有余力爱人和祷告？操练：在手机、酒精、购物或工作上设一个具体节制边界，并用省下的时间关怀一个人。'),
    n('21:37–38', '每天在圣殿，清晨听道', '耶稣白天在圣殿教导，晚上出城到橄榄山住宿；百姓清早来到圣殿听祂。路加用一个重复的生活节奏收束长篇讲论：公开教导、夜间安歇、清晨再来，直到最后冲突临到。', '耶稣在受难前仍持续教导，群众清早聚集聆听；忠心由重复的日常构成。', '末世警醒不只发生在戏剧性时刻，也发生在每天回到神的话语前。耶稣没有因知道危险临近就停止教导；祂的坚持让门徒看见，见证是一种持续的生活方式。', '橄榄山与耶路撒冷相邻，朝圣者和乡间住宿形成古代城市节奏；圣殿既是敬拜处也是公共教学空间。路加把耶稣的最后日子写成教导与听道的共同体，而不只是政治冲突。', '可对照申 6:6–9、诗 1:1–3、徒 2:42；路 4:16、24:52–53 形成从会堂、圣殿到教会敬拜的首尾呼应。', '讨论：我们的信仰是否只靠偶尔的大聚会，缺少清晨般的持续聆听？操练：为小组设一个简单的两周节奏：一次共同读经、一次彼此关怀、一次按经文行动。'),
  ],
  22: [
    n('22:1–6', '黑暗中寻找一个出卖的机会', '除酵节和逾越节临近，祭司长和文士想杀耶稣，却害怕群众。撒但进入犹大的心，他去找他们商量怎样把耶稣交给他们；他们欢喜，约定给他钱。圣城准备过节，权力却在暗处安排死亡。', '宗教领袖谋杀耶稣，犹大同意出卖；路加把人的责任与黑暗势力同时写出，却没有把任何一方变成无罪的工具。', '耶稣的受难不是偶然失控，却也不是说背叛者因此没有责任。经文让我们看见：恐惧群众、贪图利益、权力算计和属灵黑暗可以彼此勾连。最危险的恶常以“安排”“机会”和“合理程序”的样子出现。', '逾越节纪念出埃及，耶路撒冷人口暴增，祭司长担心公开逮捕引发骚乱；“撒但进入”表达邪恶势力在事件中的作用，不取消犹大的选择。', '可对照出 12 章、诗 41:9；亚 11:12–13 可作为“以价银交付”的较间接主题联读，不是路加在此处直接引用；约 13:2、徒 2:23、雅 1:14–15 继续讨论神的计划、人心欲望与责任。', '讨论：我在什么压力下会把人当成工具，或把不诚实说成“只是机会”？操练：检查一项暗中进行的决定，主动引入透明、问责和利益冲突披露。'),
    n('22:7–23', '一张桌子上的新约', '逾越节的日子到了，耶稣与门徒坐下。祂说自己在受苦以前很愿意和他们吃这逾越节，又拿起饼和杯，解释身体为他们舍、血为他们流，是神与人立新约的记号。桌边同时坐着将要卖祂的人。', '耶稣在逾越节筵席中以饼和杯解释自己的受死，建立记念祂的群体，并把这死放进新约与救赎的框架；“赦罪”是结合整本新约进一步展开的神学理解，不是本段每一句都直接说出的字眼。', '耶稣不是被动遭遇死亡，而是主动把死亡交给救赎意义。饼和杯把“为你们”放在中心：新约不是抽象制度，而是主为具体的人舍己。恩典的桌边也坐着不完全的门徒，教会因此需要诚实、悔改与彼此守望。', '逾越节以羔羊、出埃及和家庭筵席记念神救赎；新约语言回响出 24:3–8 的血与约，也连接耶 31:31–34 的律法写在心上。杯的具体顺序与保罗传统略有差异，重点是耶稣对受死的解释。', '可对照出 12、出 24:3–8、耶 31:31–34、赛 53:10–12；林前 11:23–26、来 9:11–15、彼前 1:18–19 继续展开记念与新约。', '讨论：我们领受圣餐时，是只完成仪式，还是重新接受“主为我舍己、我也属于新群体”的身份？操练：下一次圣餐前先与一位组员处理一个未和好的关系，不能和好时也诚实寻求牧养帮助。'),
    n('22:24–30', '谁为大？坐席者要学习服事', '圣餐之后，门徒又争论谁为大。耶稣指出外邦君王辖制人民，门徒却不可如此；在他们中间为大的，应当像年幼的，作首领的应当像服事人的。祂把自己放在“服事人的”位置。', '耶稣以自己的服事重定义领袖，向门徒应许国度中的席位，却不允许这应许变成辖制人的特权。', '基督徒领导不是没有权责，而是权责首先保护和成全别人。耶稣承认门徒将来要坐席、审判以色列，却先让他们看见王在桌边服事；未来身份不能成为今天压人的借口。', '古代君王以“恩主”身份施惠，也可能以恩惠建立依附；耶稣区分门徒与这种权力逻辑。餐桌、坐席和服事在当时具有明确等级意义，耶稣把等级翻转成责任。', '可对照撒上 8:10–18、结 34:1–16；约 13:1–17、腓 2:3–8、彼前 5:2–3 说明基督样式的领导。', '讨论：我在家中、教会或工作上拥有的权力，最常服务谁的方便？操练：询问被你带领的人“什么会让你更有能力”，然后实际移交一项信息、资源或决定权。'),
    n('22:31–38', '西门，你回头以后要坚固弟兄', '耶稣对西门说撒但想筛他们，祂已经为西门祈求，叫他不至于失了信心；但西门还自信地说愿意同主下监、同死。耶稣预告鸡叫以前他会三次不认主，却仍说他回头以后要坚固弟兄。', '耶稣预告彼得失败，却没有把失败当作最后身份；祂以代求和回转托付彼得未来的牧养。', '真正的坚固不是从未跌倒，而是被主在失败中挽回后，能温柔地扶持别人。彼得的自信需要被现实拆破；耶稣的祷告不让他免于一切失败，却保守他不被失败吞没。', '“筛”是谷物筛选的图像，表达群体将经历剧烈震动；门徒谈刀剑，反映他们仍以武力和政治冲突理解局势。耶稣没有把“买刀”发展成武装命令，随后反而制止暴力。', '可对照摩 9:9、亚 13:7、诗 51:10–13；约 21:15–19、加 6:1–2、林后 1:3–4 说明失败后坚固别人的道路。', '讨论：我是否因害怕失败而不敢承担，也是否因过度自信而不听提醒？操练：与一位成熟同伴分享一个脆弱处境，请他为你守望；将来不要隐藏失败，学习把被安慰的经验转成安慰别人。'),
    n('22:39–46', '橄榄山：在极深痛苦的祷告中顺服', '夜里，耶稣照常到橄榄山，门徒跟着。祂吩咐他们祷告免得入了迷惑，自己离开一点，俯伏祷告：父啊，若你愿意，就把这杯撤去；然而不要成就我的意思，只要成就你的意思。门徒因忧愁睡着。', '耶稣在极深痛苦中真实求父挪去苦杯，却最终顺服父旨意；按路加现存的通常文本，天使加添力量，门徒需要警醒祷告。', '顺服不是没有愿望、没有汗水的冷静决定；耶稣把恐惧和愿望完全带到父面前。祂没有把痛苦当作值得追求的美德，却在无法绕过的道路上选择爱与忠诚。门徒的睡着提醒我们，善意不等于有力量，需要具体的祷告节奏。', '路加只说耶稣照常到橄榄山，并没有在这里使用“园”或“客西马尼”这个名称；“客西马尼园”是平行经文的称呼。第 43–44 节在部分古抄本中缺少或被置于括号、脚注，关于其原始文本地位有重要讨论；保留在正文的版本则把它读作天使坚固耶稣、显出其真实痛苦的见证。', '可对照诗 42:5、赛 51:17、耶 25:15；来 5:7–9、罗 8:26、太 26:36–46 继续说明祷告、顺服与软弱。', '讨论：我是否把“顺服神”说成不可以表达害怕？操练：用“我渴望什么／我害怕什么／我愿意怎样交托”祷告，并在需要时让可信任的人陪你面对危机。'),
    n('22:47–71', '被亲吻出卖、在黑暗中受审', '犹大用亲吻作记号，耶稣却称他为朋友；门徒想用刀抵抗，耶稣医治被削掉耳朵的人。随后祂在大祭司院子被审问，彼得在火光边三次否认，公会清晨聚集要求祂回答：你是基督吗？耶稣承认自己是人子。', '耶稣拒绝暴力和秘密反击，在不公审问中持守真理；彼得的否认与耶稣的忠心形成对照。', '耶稣的王权在被捕时显明为医治敌人、承受羞辱、说真实话；祂没有以神迹逃避十字架。彼得不是因为不爱主才失败，而是在压力中被恐惧压倒；这为后面的恢复留下空间。', '逾越节夜间、圣殿警卫、大祭司院落和罗马统治构成复杂权力网络。在罗马统治下，路加叙事随后把致死的政治指控转到彼拉多面前；关于公会当时具体法律权限的边界，历史重建较复杂，不在此处作过度断言。', '可对照赛 50:4–9、53:7–12、诗 27:12；约 18:1–27、徒 4:8–12、彼前 2:21–23 共同见证受苦仆人的沉默与真实。', '讨论：我在群体压力下最容易否认什么？操练：预先写下三句在压力中仍要守住的真话，同时为失败预备回转路径，而不是只靠临场勇气。'),
  ],
  23: [
    n('23:1–25', '王与巡抚之间，谁在审判谁', '清早，耶稣被带到彼拉多面前，领袖把宗教指控换成政治罪名，说祂禁止纳税、称自己是基督王。彼拉多查不出祂有什么该死的罪，又把祂送到加利利王希律那里；希律想看神迹，却只得到沉默和戏弄，最后耶稣被送回彼拉多。', '耶稣在彼拉多和希律面前被查问、戏弄；政治权力彼此推诿，却仍把无罪者交给群众要求钉十字架。', '耶稣的沉默不是认罪，而是拒绝把自己变成权力娱乐。彼拉多多次说查不出罪，却为了政治安稳把祂交出；经文提醒我们，知道正确却不愿承担代价，也会参与不义。', '彼拉多是罗马总督，负责维持秩序；希律安提帕统治加利利。两者关系可能紧张，路加写出他们因审理耶稣而暂时成为朋友，但不能把政治细节扩展成确定史实。罗马刑罚决定了“钉十字架”的政治性质。', '可对照诗 2:1–4、赛 53:7、诗 22:12–18；徒 4:25–28、提前 6:13、约 18:28–19:16 继续说明权力、无罪与交付。', '讨论：我是否曾为了避免冲突，明知不公却选择“大家都这样”？操练：在工作或群体中遇到责任推诿时，用事实记录、清楚表达和安全的问责渠道守住真相，不用谣言报复。'),
    n('23:26–31', '走向刑场的路上，耶稣仍看见哭泣的人', '古利奈人西门被抓来替耶稣背十字架，妇女和人群跟随哭号。耶稣转身对她们说，不要为我哭，要为自己和自己的儿女哭；祂引用“青绿树”和“枯干树”的反差，指出即将临到耶路撒冷的审判。', '耶稣在走向十字架时仍宣讲审判与悔改，不让群众只停在情绪性的同情。', '十字架不是一场让观众哭完就离开的悲剧；它要求人面对自己、城市和暴力系统。西门的参与也显示门徒道路可能被迫进入意外承担，但经文没有把他的遭遇浪漫化。', '罗马士兵可以强迫路人承担运输，西门来自北非古利奈，可能是来耶路撒冷过节的朝圣者。青绿树与枯干树是先知式隐喻：若无罪者也被这样对待，拒绝神的城将面对更深后果。', '可对照结 21:3–4、何 10:8、耶 25:29；路 19:41–44、罗 8:17、来 13:12–13 把耶稣受苦与群体呼召连起来。', '讨论：我对受苦者的同情是否停在眼泪，还是会面对造成痛苦的结构？操练：为一个受苦新闻找出可靠背景和实际援助，不消费受害者的故事，也不把自己想象成救世主。'),
    n('23:32–43', '十字架上仍有赦免与应许', '耶稣被钉在两个犯人中间，士兵、官府和群众都讥诮祂。祂却为加害者祈求赦免；其中一个犯人承认自己受罚是应得的，却相信耶稣仍会记念他。耶稣应许他今日要同祂在乐园里。', '耶稣在十字架上为敌人代求，并向悔改、承认需要的人应许与祂同在。', '十字架上的赦免不是说暴力没有责任；耶稣的祷告把审判交给父，不让仇恨继续复制。那个犯人没有时间完成补偿，却以诚实承认和信靠来到王面前；恩典不以剩余时间长短计算。', '钉十字架是罗马公开羞辱和威慑的刑罚；两人被称为作恶的或罪犯，具体罪名经文没有交代，不能直接把他们等同于巴拉巴式的暴动者。乐园是与神同在、安息与义人盼望相连的图像，不能用来建立完整的死后地理。', '可对照赛 53:12、诗 22:7–18、创 3:22–24；路 6:27–36、林后 5:19、彼前 2:23–24 都把赦免与受苦的基督连接起来。', '讨论：在受到不义对待时，把审判交给神和寻求公义如何同时进行？操练：为一个伤害你的群体祷告求神制止邪恶、保护受害者并改变加害者，不把“饶恕”当作取消安全边界。'),
    n('23:44–49', '黑暗、裂开的幔子与最后的呼喊', '从正午到下午三点，黑暗笼罩全地。圣殿的幔子裂开，耶稣大声说“父啊，我将我的灵魂交在你手里”，说完便断气。百夫长看见所发生的事，归荣耀给神；群众捶胸，远处的妇女观看。', '耶稣把生命交给父而死；黑暗与幔子裂开把神同在、罪与进入的问题带到十字架面前。关于幔子所象征的“进入神同在的道路重新开启”，是结合整本新约作出的神学解释，路加在此处没有另作说明；百夫长至少承认耶稣是义人。', '耶稣的死不是生命被夺走后沉默结束，祂以祷告把自己交托。幔子裂开不应被简化成“人可以随意接近神”；结合来 10:19–22 等新约经文，可以把它理解为基督献上所开启的道路，但这不是路加在本节直接解释的含义。百夫长在刑场上成为意外见证者。', '黑暗、地震和幔子在古代叙事中表达哀悼、审判和圣所秩序被震动；路加没有写地震，却强调祷告、无罪和外邦人反应。百夫长是执行刑罚的军官，身份使他的见证格外具有张力。', '可对照摩 8:9–10、诗 31:5、出 26:31–33；来 10:19–22、罗 3:21–26、约 19:30 继续解释十字架与亲近神。', '讨论：我怎样面对神似乎沉默、世界似乎黑暗的时刻？操练：用诗 31:5 的话为一件无法掌控的事祷告，同时允许自己哀悼，不急着把黑暗解释成光。'),
    n('23:50–56', '约瑟把盼望安放在新坟墓里', '亚利马太的约瑟是公议会成员，却没有同意他们的决定；他等候神国，向彼拉多求耶稣的身体，用细麻布包好，安放在从未葬过人的坟墓里。妇女看见坟墓和安放的身体，回去预备香料和香膏，按诫命安息。', '耶稣真实死去并被安葬；妇女成为安葬细节的见证者，复活清晨的发现因此有真实地点可回到。', '复活不是绕过死亡的幻觉；路加先让读者停在封闭的坟墓和安息日的静默中。约瑟在制度内部作出公开承担，妇女在哀伤中预备香料；忠心有时表现为把一个死去的人好好安放。', '犹太安葬通常重视尽快处理尸体；经文写妇女按安息日诫命安息，但第一世纪安息日是否允许准备香料等具体历史细节仍有讨论。新坟墓、细麻布和香料构成古代葬礼背景。亚利马太地点和约瑟身份没有更多确定资料，不应把传统细节当成经文事实。', '可对照赛 53:9、申 21:22–23、诗 16:9–10；约 19:38–42、罗 6:3–5、林前 15:3–4 共同见证死亡、埋葬与复活。', '讨论：在还没有看见答案的“安息日”里，什么仍然值得忠心去做？操练：陪伴一位哀伤者完成一件具体事务，不急着说“很快会好”，让忠心的照顾承认死亡的重量。'),
  ],
  24: [
    n('24:1–12', '妇女来到坟墓，石头已经滚开', '七日的第一日清早，妇女带着预备好的香料来到坟墓。她们发现石头滚开，里面没有主的身体；两个穿着发光衣服的人提醒她们：为什么在死人中找活人？妇女回去报告，门徒却以为是胡言，彼得跑去查看。', '耶稣照自己所说的已经复活；妇女先听见、看见并报告，成为复活消息的第一批见证人。', '复活从一群带着香料、还没有期待复活的人开始；她们不是凭乐观推断，而是被空坟墓、天使的话和记忆中的耶稣教导重新解释现实。门徒的怀疑也被保留，说明见证不是靠删掉困惑来制造可信。', '妇女在古代社会的公共见证地位常被低估，路加却把她们放在清晨核心位置。香料反映真实哀悼和安葬习俗；空坟墓本身需要与显现和经文解释一起理解，不是孤立的证据口号。', '可对照诗 16:9–10、何 6:2、约拿 2:10；林前 15:3–8、徒 2:24–32、罗 6:4 说明复活既应验经文，也开启新生命。', '讨论：当神的作为超出预期，我是否只相信自己原先能想象的范围？操练：把一个已经被我判定“结束”的关系或使命带到神面前，不强迫结果，却为新的可能保留顺服空间。'),
    n('24:13–35', '以马忤斯路上，陌生同行者开启经文', '两个门徒离开耶路撒冷，边走边谈刚发生的事。他们眼睛被拦住，不认得耶稣；祂从摩西和众先知起，凡经上指着自己的话都给他们讲解。到村子时，他们强留这位陌生人，直到擘饼，眼睛才明亮，祂也从他们眼前不见了。', '复活的耶稣在同行、解释经文和饭桌擘饼中开启门徒，使他们从失望回到见证；擘饼有圣餐的回声，但本段没有明说这是一次正式圣餐。', '门徒说“我们素来所盼望要赎以色列民的就是祂”，说明他们的盼望并非虚假，只是被十字架重新校正。心里火热不是情绪自燃，而是在经文被打开、主与人同行之后产生；认出主也会立即带来回耶路撒冷的行动。', '以马忤斯的确切位置有不同传统，路加的重点不是旅游地图。同行、客旅接待和擘饼是古代道路生活的重要场景；耶稣解释圣经的方式，把受苦与荣耀放进以色列整体故事。', '可对照创 3:15、诗 22、赛 53、亚 12:10；路 9:22、徒 8:26–35、林前 15:3–4 继续看复活如何开启整本圣经。', '讨论：我失望时，是否只想让耶稣认同我的解释，而不愿让祂重读我的故事？操练：与一位同伴慢慢读一段旧约和一段福音，分别写“我原来以为”和“经文现在打开了什么”。'),
    n('24:36–49', '站在门徒中间，赐下平安与使命', '门徒还在谈以马忤斯的见证，耶稣忽然站在他们中间说“愿你们平安”。他们惊慌，以为看见鬼；耶稣让他们摸手脚，又在他们面前吃鱼。祂开启他们的心窍，使他们明白经文，并把悔改、赦罪和万民见证托付给他们。', '耶稣以可触摸、可见、可吃的方式让门徒确认祂不是鬼魂或纯粹的主观幻象，随后把门徒从惊恐带入理解、等候圣灵和向万民作见证。', '复活不是摆脱身体，而是身体被神更新；门徒的疑惑被耐心面对。理解经文、领受平安和被差遣是同一条路：不是只让人得到安慰，而是使人从耶路撒冷开始成为见证人。', '古代人也有关于灵魂、鬼魂和死者显现的想象，路加特别写触摸和吃鱼，强调耶稣不是一段主观幻觉。先知和诗篇指向受苦、复活、悔改与万民使命，圣灵应许把等待连接到使徒行传。', '可对照赛 49:6、诗 22:22–31、珥 2:28–32；徒 1:4–8、2:32–39、林前 15:20–28 展开见证与圣灵的使命。', '讨论：我是否把复活信仰只当作内心安慰，而没有让它改变我如何作见证？操练：准备三分钟自己的“经文—经历—当下邀请”见证，向一位愿意聆听的人分享，不夸大也不施压。'),
    n('24:50–53', '在祝福中离开，在喜乐中回到圣殿', '耶稣带门徒到伯大尼附近，举手给他们祝福，正祝福的时候离开他们，被带到天上。门徒敬拜祂，欢欢喜喜回耶路撒冷，常在圣殿里称颂神。故事没有停在失去，而是停在祝福、敬拜和等候应许。', '复活的主以祝福结束地上的显现；门徒带着喜乐回到圣殿，等待从上头来的能力。部分抄本在第 51 节的升天表述上有差异，但较长的读法是现代批判研究中通常采用的读法。', '升天不是耶稣缺席后的空洞，而是主掌权、门徒被差遣的转折。门徒的喜乐不是因为没有离别，而是因为他们知道祝福仍在、使命清楚、圣灵应许将来。路加福音的结尾把敬拜和行动并列。', '伯大尼在耶路撒冷东面橄榄山附近；“举手祝福”承接祭司和父亲祝福百姓的传统。路加—使徒行传的两卷结构从这里相接，天上主与地上见证人的关系继续展开。', '可对照民 6:22–27、王下 2:9–15、但 7:13–14；徒 1:9–14、弗 1:20–23、来 7:25 继续说明升天、代求和圣灵差遣。', '讨论：等待圣灵和未来使命，怎样不变成拖延今天的顺服？操练：用一段祝福结束本次小组：每人说出领受的一句恩典，并定下一项从耶路撒冷——自己的家庭、工作和邻舍——开始的见证行动。'),
  ],
};
